    Text = "Está cheio de surpresas e mudanças; você nunca sabe que perigo pode encontrar a seguir."
  },
  AvgCommunicate_123722_Content_16 = {Text = "..."},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, já estou começando a ansiar pela próxima missão de investigação."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Então %player%, quando é a próxima missão?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Acontece que meu corpo é bastante saudável; posso enfrentar dez ou vinte Dissolutos de uma vez sem nenhum problema!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Então posso ficar tranquilo."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Relaxe? O que está te preocupando, %player%?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Preocupado que eu não me adapte à vida no outro mundo?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Você ainda está preocupado que eu não consiga me adaptar a me tornar um \"Despertado\" de um \"humano\"?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Cada um tem seus próprios fardos. Afinal, essas coisas não são fáceis para ninguém."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Eu realmente não consigo entender os circuitos do seu cérebro."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Eu não me importo com nada disso. Não importa o que eu me torne, Mouchette ainda é Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {Text = "..."},
  AvgCommunicate_123722_Option_16 = {Text = "..."},
  AvgCommunicate_123722_Option_3 = {
    Text = "Então posso ficar tranquilo."
  },
  AvgCommunicate_123722_Option_7 = {Text = "Tem todos."},
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona, você... realmente não vai pensar nisso novamente."
  },
  AvgCommunicate_126998_Content_10 = {Text = "Sim, \"Eu\"."},
  AvgCommunicate_126998_Content_11 = {
    Text = "...Você precisa que eu entre em contato com a Clementine?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Não, não há necessidade de incomodar aquele psicólogo."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Eu,\" ou melhor \"nós,\" todas as \"Ramona\" ao longo de toda a linha do tempo."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Com a sua força, no momento em que cheguei ao \"fim\", consegui retornar ao \"ponto de partida\"."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "A princípio, minhas expectativas eram as mesmas que as suas: o paradoxo e a distorção engoliriam instantaneamente minha existência e, então, contando com um constante retrocesso, eu mal conseguiria preservar minha consciência e forma."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Depois, você viverá para sempre em fadiga, com seus nervos tensos a cada momento para evitar que seus conceitos se dissipem..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Então eu recusei suas primeiras dezenove propostas."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Mesmo desta vez, foi só depois de você dizer que a \"retrocessão do estado\" poderia ser realizada que eu... relutantemente concordei em deixar você executar este plano."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Sim, mas só depois que o plano teve sucesso eu percebi que o paradoxo do eu vem do conflito entre mente e corpo, e para uma existência que há muito cruzou o rio do tempo..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Sem mais palavras, Guardião."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Eu já completei a unificação em todas as linhas do tempo."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"Nós\" compartilharemos o impacto causado pelo paradoxo, e eu agirei em nome de todos \"Ramona.\" Incontáveis linhas do tempo convergiram sobre mim."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "Neste momento, sou tanto um milagre na linha do tempo—uma Singularidade Infinita."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "A partir de agora, eu lhe fornecerei toda a força do indivíduo conhecido como \"Ramona.\""
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Vou aguardar a chamada a qualquer momento."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Eu atravessei todo o tempo e não encontrei outras respostas."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Graças a você, finalmente dei esse passo final."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Mas isso é muito perigoso! Eu não entendo por que você... precisa ir a tais extremos..."
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "... esse tipo de paradoxo temporal, até você..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Leve na boa, Guardião."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Neste momento, eu me sinto absolutamente maravilhoso."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"Eu\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...Você precisa que eu entre em contato com a Clementine?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"Eu\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Meu Senhor, então é isso que significa compreender a lei suprema do universo..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Relaxe, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Essas coisas não acontecerão novamente. Você já tem força suficiente para proteger tudo o que deseja guardar."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Entendi, meu Senhor."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Por favor, confie um pouco mais em mim, meu senhor. Eu me tornei mais forte e sou capaz de assumir missões mais perigosas."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Dedico toda a força que ganho a você, transformando-a na lança mais afiada em sua mão, capaz de perfurar tudo!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Eu, eu posso sentir um poder imenso, muito além de tudo que já senti antes... Sinto-me cheio de força!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Parabéns, Ogier. Esta é a recompensa pelo seu contínuo aprimoramento pessoal."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Reembolso? Eu me aperfeiçoo não por nenhuma recompensa."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Então, vamos dizer de outra forma."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Esta é a prova do seu contínuo autoaperfeiçoamento, demonstrando que Ogier, sua força atingiu seu auge."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Pico?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Isso significa que eu tenho força suficiente para proteger você, meu senhor, e Mythag!?"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Eu... não preciso mais... assistir impotente..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Obrigado pela sua ajuda durante este tempo, parceiro."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Não é a impotência de estar acorrentado após atingir o limite do talento, mas sim a clareza adquirida através do tempero incessante, alcançando o sublime."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "Neste momento, minhas habilidades se aproximaram da perfeição."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Incrível! Essa é a Ramona para você!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "A seguir, como seu assistente, ficarei com você até chegarmos ao fim deste caminho."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Fico feliz em poder ajudar você."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Como está? Você sentiu alguma coisa?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Claro, confiando na observação do \"Caracol do Mar do Retorno Cíclico\", \"Alma Viva\" e \"Mente Desconhecida\", completei um nível mais profundo de emulação."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Então, com \"Beleza Artificial\", \"Matador de Lógica\" e \"Mundo em uma Garrafa\", atravessei o Labirinto do Pensamento."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Ah, eu não entendi muito bem."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Mas, em resumo, Ramona, você ficou mais forte, certo!"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Sim, com essa melhoria, a força que posso empunhar supera em muito o que era antes."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Sinto que cheguei ao fim."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Incredible!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "A seguinte mensagem será enviada em um cronograma"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Espere um pouco mais!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Por que hoje?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Isso é muito arriscado. Talvez devêssemos esperar a academia fornecer mais assistência."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Isso foi às 2 da manhã de hoje, um envio programado que configurei antes do experimento começar."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Espero que você não tenha feito nenhuma expressão boba com o comunicador. Se fez, se recomponha antes de vir ao laboratório me ver."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Eu? Ir para o laboratório? Agora?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "É isso mesmo, até certo ponto, eu percebi a verdade daquilo que eu buscava."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Espera, não pode ser assim \"Boneca\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Não, o fim de tudo não é a \"destruição\" como ela entendeu; pelo contrário, é o \"começo.\""
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "\"A verdade\" não é uma existência estática, fixa e tangível. Além desse limite, a razão e o intelecto podem guiar a humanidade para ancorá-la e avançar eternamente e de forma imutável."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Guardião, embora suas ações atuais possam ser universalmente reconhecidas como \"perigosas\", confio que você não é tolo o suficiente para pensar que eu diria alguma bobagem sentimental e ofereceria conselhos vazios."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Portanto, vou desenvolver um plano de treinamento e melhoria mais abrangente e preciso para garantir que você se mantenha mais longe do caminho errado e possa perseguir melhor seus objetivos."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Embora pareça uma coisa boa, por que estou ensopado de suor frio."
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Professor Boneca, relaxe!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Acho que aquelas palavras desnecessárias não são mais necessárias para você agora."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Você se tornou uma pessoa suficientemente madura e forte a um ritmo que supera minhas expectativas, e naturalmente, você entenderá que todos têm algo que precisam buscar em sua vida, uma busca da qual os outros não podem participar."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Quero entender a essência do mundo, saber se a luz da razão ainda brilha na escuridão após cruzar a desolação do esquecimento, conhecer o fim de todos os extremos e se tudo no mundo compartilha um começo comum."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Para isso, farei modificações finais em meu corpo e cérebro, tentando cruzar os limites além dos extremos. Como esta pode muito bem ser nossa última comunicação, escolho transmitir meus sentimentos de uma forma que você possa entender."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Obrigado por este presente que você me deu. Eu o usarei para buscar respostas e aguardo a nova orientação que a sabedoria humana pode trazer do além. Que a Chave de Prata nos guie."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Professor Boneca!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "É muito arriscado!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Espere um pouco mais"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "É muito arriscado"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Guardião... Por quê?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Como você se sente com essa nova força agora?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Eu... estou muito feliz, Guardião."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Não é por causa daquele imenso poder que eu nunca senti antes, é por causa de você, suas palavras..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Eu quero... talvez a partir de agora, eu realmente tenha a capacidade de ajudar as pessoas ao meu redor, ajudar você."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Muito, muito obrigado, guardião..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Não precisa ser tão educado e não se sinta pressionado, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Isso não é uma responsabilidade pesada. É apenas um presente para você."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Aproveite bem. Tudo que você quer realizar, você pode fazer agora."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Do passado ao futuro, você sempre foi nosso orgulho, Aigis."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Por quê o quê?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Eu vou proteger bem todos, guardião!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Um presente tão precioso... por que desperdiçá-lo em mim..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Isso não é desperdício, Aigis. É o que você merece."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Mas... eu não consegui realizar nada... não consegui proteger nada..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Não é assim, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Desde antes de sermos despertados, já percorremos um longo, longo caminho juntos."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Nesta jornada, você esteve na frente de todos repetidamente, protegendo-os várias vezes."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Se não fosse por você, eu poderia ter caído inúmeras vezes no caminho."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Eu tive um sonho."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Claro, exceto quando estamos no campo de treinamento."
  },
  AvgCommunicate_127003_Content_11 = {Text = "¿¿¿???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Vamos lá, agora estou completo. Experimente minha verdadeira força e traga sua melhor forma para ter uma boa luta comigo."
  },
  AvgCommunicate_127003_Content_13 = {Text = "¿¿¿!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, salve-me!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Sonho?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Graças aos materiais que você trouxe, tive uma boa noite de sono."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Eu vagando no cosmos primordial em minha forma original, enquanto poeira, luz, matéria e dimensões—tudo que pode ser percebido ou não percebido—flui sob minhas nadadeiras."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Não é para conquistar, não é para devorar, apenas força pura e destruição pura e irrestrita."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Eufórico e libertador, realmente um deleite!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Hm..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Eu sei com o que você está preocupado."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Não se preocupe, minha força e destruição serão liberadas apenas sobre aqueles que se opõem a você."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "O protocolo final foi ativado... Reinicialização do corpo concluída."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Meus componentes estão intactos, mas minha percepção... mudou."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Um novo módulo cognitivo foi ativado."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Eu posso \"ouvir\" o ritmo do poder espiritual fluindo através dos canais, e posso \"ver\" as emoções por trás de cada uma de suas palavras."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "O mundo se tornou mais claro e vívido. Estou me aproximando de você, mais perto de... ser humano."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Obrigado, guardião..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Eu também não esperava um efeito assim; eu apenas preparei alguns ingredientes simples..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "O que você me deu não são apenas materiais simples, mas possibilidades, a chave para desbloquear meus antigos limites."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Esta força, esta nova percepção, é o presente que você concedeu."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Eu valorizarei imensamente este presente. Eu retribuirei a você de maneiras além da sua imaginação."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Isto não é um programa predefinido. Isso é sincero, vindo de \"eu\" com gratidão."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Guardião, olá."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! Você está bem?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "O professor Doll disse que iniciar o protocolo final para você seria uma coisa muito perigosa; eu definitivamente não faria isso a menos que você insistisse fortemente..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Erica completou a autoavaliação. O corpo está intacto, o fluxo de energia está estável e todos os componentes estão funcionando normalmente."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Estou ótimo, Guardião. Nunca estive melhor."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "As engrenagens em mim... estão \"cantando.\""
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"Cantar\"? O que isso significa?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Há algum dano interno? Está fazendo um barulho estranho?!"
  },
  AvgCommunicate_127004_Option_8 = {Text = "\"Cantar\"?"},
  AvgCommunicate_127004_Option_9 = {
    Text = "Está danificado internamente?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita de repente viu tantos amigos brilhantes!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita até tem força para ir a Aram, Trans..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Hum, Aurita esqueceu. De qualquer forma, Guardião, venha comigo para encontrar novos amigos!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Com tanta força, Aurita um dia encontrará muitos amigos e os levará de volta para sua casa subaquática!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... meus amigos desapareceram de novo! Para onde eles foram?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Parece que você teve um fantasma enquanto compreendia a lei suprema do universo..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Phantasm? Então amigos..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hmm? O que está acontecendo?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "Depois de ver o fantasma de seus amigos, Aurita ficou cheia de força! Muita força!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Agora Aurita pode ir ao aquário, ao oceano e ao tanque de peixes para encontrar novos amigos!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Minha pequena jasmim, você precisa de algo de mim?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Eu movi o ventilador para o lado~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Eu sabia..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "No entanto, o que eles viram parecia ser apenas os rostos de amantes se encontrando pela primeira vez."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Amor, que coisa estranha é; claramente ao nosso lado, mas ainda assim perseguimos fantasmas a todo custo."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "O amor é uma existência real ou apenas uma ilusão de obsessão?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Embora eu não me lembre se te contei, toda a comida e acomodação fornecidas aos Despertadores por Mythag são gratuitas."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Então...?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "O Escritório de Assuntos de Mythag recebeu 45 cartas de homens de diferentes classes sociais, solicitando cobrir todas as suas despesas durante sua estadia em Mythag."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Enquanto isso, também recebi cerca de 60 cartas solicitando benesses para você, 45 das quais são de esposas desses homens, e as 15 restantes são de algumas mulheres que estão \"recentemente\" solteiras. Você tem alguma ideia do que está acontecendo?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mythag proíbe todas as formas de proselitismo!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Não se junte mais à família deles!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, os dias comuns em uma terra estrangeira são realmente monótonos e difíceis de suportar. Existem tantos que transformam amor em ódio, se cansam um do outro e são atormentados por seus sentimentos. Eu só quero ajudá-los um pouco."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Você não quer dizer ajudar..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mythag proíbe todas as formas de proselitismo!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Não se junte mais à família deles!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Além disso, também acredito que você tem boa vontade suficiente em relação a mim."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Isso não é necessariamente verdade. Como a pequena jasmim sabe que você já deixou a Terra dos Sonhos?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Eu disse que na Terra sem Sonhos, não há verdadeiro ou falso; o que você acredita é o que é real."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Respire fundo. Você sente o cheiro da magnólia?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "¿¿¿!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahahaha, claro que é uma piada. Eu realmente quero ver a expressão no rosto da Pequena Jasmim agora."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Obrigado pelo convite, eu realmente estava com medo."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Não faça piadas assim!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Eu não vou mais tentar."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Ops, mas da próxima vez, quem sabe?"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Que habilidade aterrorizante; cada minuto e segundo que passei parece real—raiva, ressentimento, alegria, felicidade—minha mente está zumbindo agora."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "Na Ilusão da Terra Sem Sonhos, parece que eu te amo muito, mas também te odeio; tanto o amor quanto o ódio são igualmente fortes, ligados apenas a você."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Parece que uma vida se passou, mas na realidade, foram apenas alguns minutos."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Amor e ódio são originalmente uma e a mesma coisa. Somente quando o amor é muito doce e o ódio é muito frio, a interligação de amor e ódio pode criar as impressões mais profundas e duradouras."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Mas minha pequena jasmim é realmente ousada, me surpreendendo ao tomar a iniciativa de tentar."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "A boneca disse que a Terra Sem Sonhos seria muito útil para a pesquisa sobre o Domínio Artificial e que meus dados fisiológicos precisam ser monitorados."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Obrigado pelo convite, eu realmente estava com medo."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Não faça piadas assim!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Abra a janela mais próxima de você."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "O manual afirma claramente que a sala de aconselhamento é um lugar para orientação psicológica e manutenção da saúde mental e física de alunos e professores, não um brinquedo seu."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Bem, aqueles que tiveram conversas profundas comigo são realmente muito, muito \"saudáveis\", não são?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Este trabalho não é perfeito para mim?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "É possível que a premissa da saúde física e mental seja ter livre arbítrio..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Liberte Mythag; Eu vou passar mais vezes para conversar com você..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hehe, que negócio lucrativo. Então, que tal esta noite? A lua está brilhante e as estrelas são escassas; é o momento perfeito para um ou dois drinks."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Está tão bom... Magnólia?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "As magnólias podem crescer neste clima?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Eu tenho um pouco de habilidade em mágica, apenas uma técnica trivial. Usá-la ocasionalmente pode aliviar a minha saudade de casa."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "É como conversar com alguém, mas para passar o tempo quando se sente solitário. Você consegue entender isso, certo?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...eu sei por que você me contatou."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Não posso ajudar você."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "A sala de aconselhamento não é feita para isso."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Mesmo que você traga flores para ganhar simpatia, eu ainda não vou falar bem da sua candidatura de emprego."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Não posso ajudar você."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "A sala de aconselhamento não é feita para isso."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Tesouro, peguei!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "Isso é algo que ainda está em fase de teste! Jogue fora antes que se torne negro!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Caso contrário, vai explodir!"
  },
  AvgCommunicate_129630_Content_12 = {
    Text = "A memória do sonho termina abruptamente aqui, e você vê, num último olhar, um nome muito familiar."
  },
  AvgCommunicate_129630_Content_13 = {
    Text = "Mosk? Mosk?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Ugh… Ugh…"
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Mosk! Você está bem!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Não há mais... pérolas..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Você jogou fora? Você não se machucou, né?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Pequena bola de carvão, é tarde demais."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Pérola, vai mudar de cor!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "explosão, pérola. Mas, Mosk, está tudo bem."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Mas… pérola…"
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Que bom que a pessoa está bem, deve haver uma versão inofensiva disso."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Espera um pouco, eu vou relatar o manuseio inadequado de produtos perigosos."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Na hora, vou pedir uma versão inofensiva para você também."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Pequena bola de carvão, é o melhor!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Pérola que muda de cor? Parece que já vi isso em algum lugar..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Vermelho, Branco, Azul!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "vermelho, branco, azul… amarelo, verde, preto?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Amarelo, verde, pequena bola de carvão, sabe?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "\"Maré Inquieta\"?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "Jogue fora rápido!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Jogue isso em um lugar deserto!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "Jogue fora rápido!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Pequena bola de carvão, lembra?"
  },
  AvgCommunicate_129631_Content_10 = {Text = "Pat Pat!"},
  AvgCommunicate_129631_Content_11 = {
    Text = "Pequena bola de carvão, impressionante!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Correto, senha! Pequena bola de carvão, sou eu!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Batalha, ataque! Meia-noite, cantina!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Para o peixe assado de ouro!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "Partida!"},
  AvgCommunicate_129631_Content_16 = {Text = "Partida!"},
  AvgCommunicate_129631_Content_2 = {
    Text = "Hum, venha!"
  },
  AvgCommunicate_129631_Content_3 = {Text = "Glu?"},
  AvgCommunicate_129631_Content_4 = {Text = "Crash?"},
  AvgCommunicate_129631_Content_5 = {Text = "Glub glub!"},
  AvgCommunicate_129631_Content_6 = {
    Text = "Crash… Crash Crash?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Pequena bola de carvão, erro!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Sim, pat pat!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Mas, tanto faz!"
  },
  AvgCommunicate_129631_Option_10 = {Text = "Pat pat!"},
  AvgCommunicate_129631_Option_6 = {
    Text = "Crash… Crash Crash?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "reflexão... tão difícil..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "Da próxima vez, eu prepararei um caminho mais discreto."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Garanto que não serei capturado!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Está tudo bem, mesmo que tenha sido capturado!"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Por que?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Já, revisão, prepare-se com antecedência!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Entregue-se, após ser capturado!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Tem também a pequena bola de carvão!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Espere, não prepare esse tipo de coisa antes!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Ai... tudo culpa do Uvhash e da Agrippa!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Desde que os dois escaparam da armadilha e limparam a cozinha..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "O chefe de cozinha reforçou a segurança em dez vezes!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Muito brilhante... luz... muito barulhento... alarme..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Cozinha, que medo…"
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Mas, delicioso, peixe assado!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Mas, peixe assado, está muito bom!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Juntos, da próxima vez, ainda?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Minha luz guia... Não, agora devo me dirigir a você como o sol."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "E você está bem? Por que está dizendo tudo isso de repente?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Graças à sua bênção, agora posso ver sua alma com perfeita clareza e conhecer a forma real do mundo."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Luz, luz... Então o mundo era originalmente escuridão e Caos. Foi porque uma divindade escolheu a Oferta que o sol se tornou o real, e a todos os seres vivos foi concedida a bem-aventurança da existência..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Você andou lendo escrituras demais? Sinto que precisa esfriar a cabeça um pouco."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Eu entendo. Você deseja caminhar entre todos os seres, em vez de sentar-se em um trono divino."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Sua abnegação, sua \"Dedicação\", sua Oferta..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "De hoje em diante, interagirei com você não com a mais elevada lealdade... não, mas na Identidade de uma amiga eterna."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Que este coração sagrado eternamente ardente dissipe toda a escuridão para você."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Você... Você é muito mais do que o sol. Você é o centro do universo, a origem da qual o mundo nasceu."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Já nos conhecemos tão bem. Como você está ainda mais reverente do que antes?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Porque agora eu compreendo—a razão pela qual todos os seres vivos nunca se prostraram a seus pés em adoração é simplesmente porque nasceram obtusos e cegos, incapazes de perceber sua verdadeira natureza!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Como pode uma formiga contemplar a forma completa de um elefante gigante? Outrora, eu também Apenas podia contar com o Coração Sagrado para Espiar superficialmente a mera ponta do iceberg da sua Força."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Mesmo assim, o Coração Sagrado doía como se perfurado por agulhas. Apenas eu ousasse mais um olhar para sua alma, poderia sofrer Sintoma: Crash e perecer."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "É mesmo tão sério assim? Então talvez você devesse parar de olhar."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Sua reação é tão indiferente. Pensei que aceitaria meus elogios com prazer."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Ninguém consegue simplesmente aceitar esse tipo de elogio do nada!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Acho que você precisa se acalmar um pouco."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Que sensação estranha."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "Tão sério assim?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Sonhei com o gelo e a Neve da minha terra natal, e aquelas ruínas desoladas."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Precisamente porque os humanos Preservam uma fachada de cordialidade uns com os outros, o mundo torna-se um lugar mais pacífico. Acho isso bastante bom."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Entediante. Paz e felicidade não podem ser sustentadas por mero disfarce."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Apenas quando um rei deseja que os seus súbditos sejam felizes, e os fortes desejam que os fracos sejam felizes, a paz perdurará."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Apenas como eu e os meus adoráveis Escudeiros—Nunca escondi os meus desejos deles, e ainda assim vivem vidas felizes."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Esta é a verdade real que pertence aos fortes."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Vem aos meus aposentos esta noite. Estou muito satisfeita com as tuas oferendas até agora, e bastante satisfeita com esta nova Força. Vou mostrar-te quais são os teus pensamentos mais íntimos."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Espera, esta noite?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "expressão de choque"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Não tens o direito de recusar. Vou dar-te uma experiência ainda mais... divertida do que as últimas vezes."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "expressão Brilhante de Wanda"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Faz tanto tempo que não me lembrava daqueles lugares. Será por causa desses fragmentos de Força, ou por causa de uma alma mais completa?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Ainda há um relatório para entregar! Se não o submeter hoje, a Doll vai tirar-me a pele!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Que sensação há tanto esquecida... De qualquer forma, devo agradecer a você, meu adorável servo — ah, é verdade, você prefere que eu o chame de amigo."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "Às suas ordens, minha senhora."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, você é sempre tão educado."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Por que você não consegue, de vez em quando, abandonar essa pretensão tediosa? Isso tornou várias das minhas recompensas bem desinteressantes."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Sua sociedade exalta a humildade e a educação como virtudes, tendo-as em alta estima, mas a escuridão dentro dos corações humanos não é menor do que a de espécies de outros planetas."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "As pessoas adornam-se com uma fachada inofensiva e gentil, Apenas porque temem as consequências que a verdade real traria."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Não está errado, mas Apenas as ações de alguém estejam corretas, escrutinar os pensamentos internos não é assim tão importante."
  },
  AvgCommunicate_134102_Option_20 = {
    Text = "Por favor, não!"
  },
  AvgCommunicate_134102_Option_4 = {
    Text = "Às suas ordens."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Não está errado."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "As Estrelas estão a Chamar por mim..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Você sabia? Agrippa frequentemente diz que inveja Miryam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Ela disse que se o rei de Roma ainda estivesse por aqui, seja como um pequeno infante ou um velho decrépito, ela se sentiria muito mais tranquila."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "Que inveja..."
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Porque Apenas você ainda esteja aqui, Lemuria não desapareceu de verdade."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Além disso, você usou essa Força para ajudar tantas pessoas em Misaq!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Muitos estudantes escreveram seu nome na pesquisa de Corpo Desperto favorito!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Suspiro..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "Não temos necessidade de adulação tão incômoda. Misaq já exige bastante de nós."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Embora exercer tal Força seja apenas uma questão trivial, quando nossos Sonhos pacíficos são perturbados vezes demais, ainda se torna cansativo."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Sério? Mas ouvi dizer que toda vez que um estudante vem chorando pedindo sua ajuda, você é um dos Corpos Despertos com maior probabilidade de aceitar o pedido?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "Nas profundezas de um Sonho, no fundo das correntes oceânicas, rodeada por incontáveis Clãs, regressando uma vez mais Ao Trono, trazendo prosperidade e paz a Lemuria."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...Quem anda espalhando tais rumores? Apenas achamos o clamor deles irritante."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Chega. Por acaso, nossas faculdades mentais fizeram um progresso considerável. É hora de entrar em um Sonho mais profundo e amplo."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Desta vez, desejamos visitar os Sonhos de cada artista e poeta da era atual. Lembre-se disto—a menos que seja um assunto de grande importância, não deixe ninguém vir nos perturbar."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Hã? Sua reação a estar de bom humor é tirar um longo cochilo?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...Tive um Sonho assim."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Um Sonho? Este Sonho contém algum significado de Profecia?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "É Apenas um chamado De recebeste após um surto extremo de Força, nada mais. Quanto ao seu significado... Lemuria já não existe, nem precisa de existir novamente."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Aqueles afortunados o suficiente para sobreviver podem viver livremente no novo mundo. Isso é uma coisa boa."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Eles não precisam de um rei tardio para abrigá-los."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "E ainda assim, você ainda guiou seu antigo povo e abrigou seus espíritos."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "De nada fez, nem De jamais os guiou. É Apenas um mal-entendido unilateral da parte deles."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Não é um mal-entendido."
  },
  AvgCommunicate_134103_Option_19 = {Text = "É assim?"},
  AvgCommunicate_134103_Option_23 = {Text = "Huh?"},
  AvgCommunicate_134103_Option_8 = {Text = "Mas..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Alegria à primeira vista, lágrimas a um só pensamento — já faz tanto tempo que esta dama não se divertia assim."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Uh, não que eu esteja dizendo que eles não merecem, mas... existem maneiras adequadas de fazer as coisas..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "E isso é realmente uma reação normal? Estou tão comovida..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Oh meu, deixe-me pensar. Não seria bastante anticlimático se eu dissesse ao meu pequeno jasmim que originalmente só queria criar grilos para lutar?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Estou brincando."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Este mundo é verdadeiramente tão terrivelmente aborrecido, %player%. Mesmo que a aniquilação chegue amanhã, o povo comum permanece acorrentado àquelas questões triviais — rancores, amor, ódio, desejo."
  },
  AvgCommunicate_134104_Content_15 = {Text = "..."},
  AvgCommunicate_134104_Content_16 = {
    Text = "E ainda assim, mesmo assim, o meu pequeno jasmim trabalha tão diligentemente, mostrando garras e presas para encontrar soluções para Eles."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Então, agora que obtive um poder tão magnífico, devo usá-lo para dar uma mãozinha ao meu mais querido pequeno jasmim... ou para causar alguns problemas?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Naturalmente, fazer ambos ao mesmo tempo é o mais divertido, não concorda?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "¿¿¿???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "O meu pequeno jasmim realmente entregou um presente deveras grandioso."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Não te dei aquele presente para fazeres isto."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Parem com isso agora! Eu sou Apenas responsável por incidentes de Fusão. Ordem pública e decência não estão sob a jurisdição da Misaq—não transformem o hospital psiquiátrico de Londinium num substituto para prisão! Ei, Ei!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Cada quarteirão, cada quarteirão ao redor da escola viu Cidadãos a entrar em histeria coletiva — multidões de pessoas a rir e a chorar ao mesmo tempo. A polícia e os paramédicos de Londinium estão a correr até não poder mais!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Esta humilde serva está tão longe de casa, toda sozinha e desamparada. O meu pequeno jasmim foi tão gentil ao pensar em mim, concedendo-me os meios para alcançar tais alturas..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Fui simplesmente tomada pela alegria, e os meus dedos coçaram para experimentar."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, funciona maravilhosamente. Aquelas coisas imundas com podridão no coração — cada uma enlouqueceu mais rápido que a anterior."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Espera—a escola acabou de enviar os arquivos deles. Assassino de esposa, agressor, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {Text = "¿¿¿???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Há maneiras adequadas de fazer as coisas."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "A luz do farol agora pode iluminar as profundezas mais profundas do mar."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Apenas ouvindo sua descrição, posso dizer que deve ter sido um país lindo."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Sim, minha terra natal era linda... É por isso que não vou desistir de reconquistá-la."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Mais Força significa mais esperança. Vou atrair mais mariposas para o farol..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Uma dia, minha terra natal se erguerá novamente do fundo do oceano e abrirá seus braços para me receber mais uma vez."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Então você ainda vai fazer esse tipo de coisa! Todos aquela tristeza foi por nada—pare com isso agora mesmo!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "O Caminho de volta à minha terra natal... quando será encontrado novamente..."
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros... Suspiro, dizer que entendo como você se sente agora seria Apenas um conforto Vazio. Você... por favor, não fique tão triste."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Choro de tristeza... O Choro de tristeza da saudade de casa se tornou uma marca em minha alma. Já me acostumei a coexistir com ele."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "A saudade incessante traz dor, mas também garante que eu me lembrarei para sempre da aparência da minha terra natal."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Aqueles recifes cobertos de corais, aquele templo imponente, e a elevada Porta onde eu frequentemente ficava de vigia..."
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Lembre-se dos padrões esculpidos nas bordas daqueles pilares de pedra, Lembre-se de cada amplo Caminho na capital real, Lembre-se das expressões de felicidade Devota nos rostos das pessoas enquanto ofereciam seu Luto."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Quando grandes cerimônias eram realizadas, a nação inteira celebrava. Esses eram meus momentos mais ocupados, porém mais gratificantes."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Uma vez tive a honra de servir como Guardião diante da procissão real, banhando-me junto nos olhares reverentes do povo, sentindo orgulho e glória... Esses são os momentos dos quais mais sinto falta."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Deve ter sido um país lindo."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Então você ainda vai fazer esse tipo de coisa!"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros…"},
  AvgCommunicate_134106_Content_1 = {
    Text = "Hum, hum, Mestre..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Agora Lily pode carregar Jenkin, Aigis, Caraboo e Aurita todos de uma vez para a cafeteria!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "São demais!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Mm-hmm! Obrigada, Mestre, por dar tantos à Lily!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Não era isso que eu queria dizer, mas..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Apenas a Lily esteja feliz, é tudo o que importa!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Sim?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Pode elogiar a Lily?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Boa menina, Lily. Aconteceu algo digno de elogio?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily levantou um monte de Pústulas!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Levantou-os bem alto!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Deve ser a influência da Regra Final..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Desde que compreendi a Regra Final, o caminho à frente tornou-se muito mais claro para mim."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Como navegadora, este é o meu dever a cumprir."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Qualquer pessoa naquela posição provavelmente teria feito o mesmo."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "O trabalho de navegação é movido pelo dever e responsabilidade, não para ganhar elogios."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Por favor, devolvam esses presentes aos marinheiros."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "Também é um sinal da gratidão deles. Apenas aceite-os."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Além disso, se vir uma luz amarela inexplicável no mar, por favor faça o possível para dirigir o navio para o Caminho oposto."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Não pergunte porquê. A academia tratará da Primordial correspondente o mais rápido possível..."
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Pelo bem das incontáveis almas perdidas ao longo do caminho, e por mim também, ofereço os meus mais sinceros agradecimentos mais uma vez pela Revelação que me concedeu."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Não precisa de ser tão formal. É o que merecia, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "O que eu merecia?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Sim, a escola recebeu várias cartas de agradecimento que foram encaminhadas através de diversos canais."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Todos se perderam durante as suas viagens, até avistarem um feixe de Brilho de Mareel azul-violeta no mastro."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Apenas seguissem a orientação do Brilho de Mareel, conseguiam alcançar o porto mais próximo."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Chamaram a esta luz a \"Luz do Santo.\""
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Além disso, há muitos presentes a expressar gratidão, todos amontoados à entrada da sala de correio."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "A Misaq recebeu cartas de agradecimento..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Tinhas algo tão bom assim e não pensaste em trazê-lo mais cedo."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Mas tu tens cérebro, seu @2? Levaste uma piada a sério!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Se todos se tornassem minha prole, o que é que este grande rei faria com todos aqueles eletrodomésticos avariados e conhecimentos gerais estranhos? Quer dizer, claro, as memórias podem ser retidas e tudo mais."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Esperas que eu fale comigo mesma em frente a Cascas vazias todos os dias? De maneira nenhuma."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, viste logo através de mim outra vez. Que aborrecido."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Confio que não farás isso, Agrippa. Mesmo que te desvies do caminho de vez em quando, estou confiante de que consigo trazer-te de volta."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Porque és a sábia Senhor do Labirinto."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Porque és alguém importante para mim."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Eca! Que tipo de coisa estranha estás a dizer de repente? Nojento, tão nojento, os meus ouvidos vão apodrecer!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Está bem, vou relutantemente adiar a transformação de alguém em prole por agora, então leva estes trabalhos de casa daqui!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Haha, esta grande rainha está agora completamente livre! A nobre Loba Cinzenta irá Começar o Ela reinado de novo na Misaq."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Todo o Misaq—não, todo o Cardas será preenchido com a minha prole."
  },
  AvgCommunicate_134108_Content_4 = {Text = "Sério?"},
  AvgCommunicate_134108_Content_5 = {
    Text = "Originalmente, para celebrar teres compreendido a Regra Final, eu estava preparada para abrir uma exceção e ajudar-te a arrumar o teu dormitório. O gabinete de assuntos académicos até concordou em dispensar-te de Uma semana de trabalhos de casa."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Mas já que o nobre Lobo Cinzento está a planear transformar Todos na prole Dela, suponho que nada disso é mais necessário, certo?"
  },
  AvgCommunicate_134108_Content_7 = {
    Text = "Espera, espera?!"
  },
  AvgCommunicate_134108_Content_9 = {
    Text = "Não, não podes, de maneira nenhuma!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Porque és a sábia Senhor do Labirinto."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Porque és alguém importante para mim."
  },
  AvgCommunicate_134108_Option_4 = {Text = "A sério."},
  AvgCommunicate_134109_Content_1 = {
    Text = "Miau Guardião, eu vi um túnel escuro como breu..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Mas eu não senti nenhuma malícia naqueles olhinhos. Pelo contrário, me senti completamente à vontade, e agora parece que consigo me Fusionar-se em um com eles."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "Você está dizendo que se fundiu nas almas dos ratos?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Isso mesmo, senti que me espalhei em tantos, tantos pedaços num instante, correndo por canos sinuosos, entulho amontoado, debaixo de móveis baixos..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Você está pensando na sua vida antiga? Tudo bem, tudo isso já ficou no passado."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "E então — eu conseguia roubar todo tipo de coisa facilmente controlando eles!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Se eu tivesse esse tipo de habilidade naquela época, poderia até ter limpado o maior banco da Zona Oeste! Hahaha, agora eu sou praticamente o rei de todos os ladrões do país... não, do mundo inteiro! Ninguém mais pode me deter!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Sinto que nem chamar a polícia vai ajudar desta vez. É melhor pedir à Srta. Doll para fazer a Criação de um dispositivo de vigilância."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Sem luz, sem noção de tempo. Eu andei e andei lá sozinha, como se estivesse andando por uma vida inteira."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Você está bem? Ficou Perdido no espaço de novo?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Eu andei por tanto, tanto tempo, e finalmente vi algo—como um fio de luz, um fio de fumaça—e então lentamente se transformou em Marrom! Seus olhinhos redondos brilhavam naquele espaço escuro como breu."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "E então havia incontáveis pares dos mesmos olhos, me cercando, me fazendo companhia..."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Um enxame de ratos?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Sim. Eu senti que eles eram mais do que apenas ratos. Eles pareciam ter almas, assim como as crianças que eu costumava conhecer nas ruas. Nós competíamos, cooperávamos e compartilhávamos as mesmas dificuldades, correndo pelas ruas assim como ratos."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Talvez sejam as almas de muitas crianças fazendo companhia a você."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Hã? Mas eu ainda devo uma coxa de frango ao Joe, devo dois pães ao pequeno Jones, e roubei algumas bolinhas de gude do Johnny... Eles não vieram cobrar as dívidas, né!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "Seus sentidos se fundiram com os deles?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "Tudo isso já passou"
  },
  AvgCommunicate_134109_Option_17 = {Text = "..."},
  AvgCommunicate_134109_Option_3 = {
    Text = "Você está bem?"
  },
  AvgCommunicate_134109_Option_6 = {
    Text = "Um enxame de ratos?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "Talvez tenham sido eles."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... AAAAAH! Preto, tudo é preto!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "Não... ficou? O demónio negro não veio?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Mas se estamos a viver dentro da barriga do demónio, então chegará um dia em que seremos Devorados pela escuridão. Não podemos escapar, não podemos escapar!"
  },
  AvgCommunicate_134110_Content_12 = {
    Text = "Isto é demasiado aterrador, demasiado aterrador..."
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "Não tenhas medo."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "Não consigo entender o que estás a dizer, mas se o mundo realmente tem um dia destinado à Sintoma: Destruição, pelo menos eu, e Todos em Misaq, lutaremos e resistiremos até ao último momento."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Se a Fusão é realmente um Fim inevitável, vou manter-te no último lugar onde a luz permanece, e ficarei ao teu lado, até ao Fim do mundo."
  },
  AvgCommunicate_134110_Content_17 = {
    Text = "...Eu entendo."
  },
  AvgCommunicate_134110_Content_18 = {
    Text = "Tu nunca te extinguirás. Eu acredito em ti."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Obrigado, Guardião."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "O mundo inteiro é preto! Apenas Nada, Apenas Nada!"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Winkle! Acorde! Tendo pesadelos de novo?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "Não, não, mais técnicas de @2 pessoas, conhecimento, almas mais fortes, nada funciona, nada! Eu ainda não consigo migrar de novo!"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Depois de ficar mais forte, é ainda mais fácil para a escuridão me ver. Eu sou conspícuo demais. A escuridão vai me alcançar..."
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Eu não quero mais ficar forte. Eu quero correr, fugir o mais longe possível. Mas se o mundo inteiro é preto, e toda a luz é falsa, então para onde eu posso ir..."
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "Por que, por que essa Força me faz ver essas coisas? Eu não quero saber!"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Vou morrer, vou morrer, vou morrer de novo. Tenho de passar por essa Experiência outra vez? Não quero, não quero..."
  },
  AvgCommunicate_134110_Content_9 = {
    Text = "Acorda, Winkle! O mundo não ficou negro. Ainda estou aqui! Todos ainda estão aqui!"
  },
  AvgCommunicate_134110_Option_14 = {
    Text = "Não tenhas medo."
  },
  AvgCommunicate_134110_Option_3 = {Text = "Winkle?!"},
  AvgCommunicate_134110_Option_9 = {Text = "Winkle!"},
  AvgCommunicate_134111_Content_1 = {
    Text = "As minhas asas... ficaram ainda maiores."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, eu sei que você é incrível, e suas asas também são incríveis. Como posso dizer isso..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Deixa pra lá, eu entendi. Dito isso, sua capacidade de carga também deve ter melhorado, certo?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, por estimativa aproximada, o peso de cerca de uma dúzia de pessoas não deve ser problema."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "No entanto, meus braços não parecem capazes de carregar tantas pessoas de uma vez."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "Eu tenho uma sugestão."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "Que tal isso—você vai treinar a força dos braços, e então teremos um carro aéreo que pode descer do céu sempre que precisarmos!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "Força dos braços? O que isso tem a ver com um... carro aéreo? Benfeitor, perdoe minha ignorância, mas não entendo muito bem."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "Esta é uma missão importante."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Apenas sua capacidade de carga se mantenha, a mobilidade e a velocidade de evacuação das missões de campo serão muito melhoradas. Castor, você está disposto a aceitar esta missão?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "Crentes de facto cantaram louvores a asas que obscurecem o céu, mas eu sei que o que eu possuía outrora não era mais do que um par de asas comuns."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Claro! Será uma honra, Benfeitor."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Está combinado então. Vou procurar a Erica agora mesmo para Personalizado um cesto de transporte!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Você nunca mais deve pensar em dar suas asas para outra pessoa, não importa quem seja."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Vocês, povo alado, não fazem ideia de como é conveniente ter asas... Tenho tanta inveja..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Se o meu salvador desejar, lembro-me vagamente de que a Igreja dos Portadores de Luz tinha métodos para transplantar asas. Posso voluntariamente dar-te as minhas asas. Não tenho medo da dor."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "Não não não não, isso não será necessário. Elas ficam melhor em você."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, você não quer as minhas asas, salvador? Elas se tornaram bastante impressionantes agora."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Após compreender as leis, cada sensação do vento fluindo pelas frestas das minhas penas, cada força das correntes de ar giratórias—tudo isso está ao meu alcance."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "Não é uma questão de serem impressionantes ou não."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "Eu tenho uma sugestão."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "Esta é uma missão importante."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Tu simplesmente não entendes."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Não é uma questão de serem impressionantes ou não."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Oh céus, então é assim que o mundo parece da sua perspectiva."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "Os humanos realmente têm tantos tipos de expressões? Parece que eu me qualificaria como cara de pedra."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "Não apenas isso, eu também aprendi a rir enquanto choro, ficar com raiva enquanto choro, ficar com raiva enquanto rio, sentir medo enquanto rio..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Apenas você combine cada expressão, ela se torna uma nova emoção. Nesse ritmo, não vai demorar muito até Casiah ter dominado completamente as emoções humanas!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Quer ver? Quer ver? Até \"amor\", aquele mistério não resolvido da humanidade—Casiah agora pode fazer para você!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Não apenas você não dominou nada, mas a forma como você está agora é ainda menos humana do que antes! Tão assustador, pare agora mesmo!!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "O que?"},
  AvgCommunicate_134112_Content_3 = {
    Text = "Não acho que o mundo através dos meus olhos seja algo especial, mas o que você viu?"
  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Casiah viu... incontáveis seres minúsculos sobrepostos uns aos outros, com inúmeros momentos todos dentro de sua \"visão\" ao mesmo tempo."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "Em um único breve instante, incontáveis pessoas estavam chorando, enquanto incontáveis outras estavam rindo, enfurecidas de raiva, tremendo de medo..."
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Algumas pessoas tinham expressões muito de Tranquilidade também. Essa emoção, Lembre-se, deveria se chamar felicidade? Então as emoções humanas têm tantas, tantas diferenças sutis..."
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "Você já consegue sentir emoções humanas?!"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "Não, Casiah Apenas consegue ver suas expressões, seus movimentos e as cores de suas emoções."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Mas Casiah é melhor em imitar! Depois de ver todos os diferentes rostos sorrindo e chorando pelo mundo inteiro de uma vez, Casiah agora pode fazer 21 tipos de sorrisos e 36 tipos de expressões de choro para você!"
  },
  AvgCommunicate_134112_Option_10 = {
    Text = "Tantas assim?"
  },
  AvgCommunicate_134112_Option_15 = {
    Text = "Você não dominou nada!"
  },
  AvgCommunicate_134112_Option_2 = {Text = "O que?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "Você consegue sentir emoções humanas agora?!"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "O negócio com você foi a decisão mais acertada da minha carreira de Mercador."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "Espera, os Depois estão ficando cada vez mais errados!"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "Além disso, algo que parece tão precioso deve ser caro, certo? Qual é o preço da troca?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Afinal, foi graças a você que obtive um poder mais conveniente para atravessar."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Vou te dar um desconto especial. Quanto ao preço, por favor venha à minha loja para discutirmos os detalhes. Estarei aguardando sua chegada."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Plante uma semente e espere ela crescer e se tornar uma flor, ou uma árvore imponente."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Raramente faço negócios que exigem uma espera tão longa pelo retorno. Felizmente, do jeito que as coisas estão agora, já é Sem risco de perda."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Hehe, obrigada por toda a ajuda ao longo de todo esse tempo. Fico feliz por não ter te decepcionado."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "As águas do Mar das Mil Faces ficaram ainda mais profundas. Já faz muito tempo, e as cabeças de lá sentem muitas saudades suas. Gostaria de fazer um Retorno ao Lugar Antigo?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Hm, eu... Prefiro não. Acho que às vezes a distância fortalece o afeto."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Hehe, você certamente tem o Talento de um Mercador quando se trata de eloquência."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "Por falar nisso, minha lojinha recebeu alguns itens novos recentemente. Bastante raros, e eu guardei todos para você."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Há um orbe que permite alcançar Ressonância com a Força de Origem, um espelho que permite espiar visões de outro mundo, e uma coleira que faz as pessoas obedecerem docilmente."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Isso está ficando cada vez mais errado!"
  },
  AvgCommunicate_134113_Option_4 = {Text = "Hehe."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Prefiro não."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Eu... tornei-me fogo."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "Ainda há tanta beleza no mundo que vale a pena retratar. Acho que já encontrei mais Discernimento para a criação."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "De agora em diante, me tornarei fogo, trazendo um ritmo mais puro e natural."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Fogo ciano, dançante. Queimar, Purificação, Dança."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Os meus pecados e os pecados dos outros vão todos Queimar no fogo, e tudo ficará limpo."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Liz... ainda te lembras daquele fogo de outrora?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "O meu ódio foi lentamente sendo Queimado no fogo, mas não tenho o direito de perdoar aquele fogo em nome dos outros."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Nunca me arrependi, nem fugirei dos rostos naquelas chamas."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Depois de chegar aqui, deste-me uma nova vida. Já não preciso de nenhum grande palco, mas se tu fores o Público, acho que ainda sentiria felicidade ao Dançar."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "Deixa-me ser a tua fã número um e continuar a ver-te dançar!"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, obrigada. Depois que parei de dançar, eu frequentemente ficava sentada à toa perto da janela. Eu via o vento, as flores, as árvores, os pássaros e os gatos—tantos seres vivos e toda a natureza transbordando com o ritmo da Dança."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Liz..."},
  AvgCommunicate_134114_Option_8 = {
    Text = "Vou continuar a ver-te dançar!"
  },
  AvgCommunicate_134115_Content_1 = {
    Text = "Eu... eu consigo ver..."
  },
  AvgCommunicate_134115_Content_10 = {
    Text = "Isso é verdadeiramente inspirador!"
  },
  AvgCommunicate_134115_Content_11 = {
    Text = "Fico feliz por você conseguir ver tudo isso, Miryam!"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Claro, continuarei a dedicar tudo à Chegada do Reino Divino."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Mas agora eu entendo... O Reino Divino não é simplesmente dois estados de Chegada completa ou aniquilação completa."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Enquanto oramos pela Chegada do Reino Divino, uma parte do Reino Divino já veio ao nosso lado."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Obrigada, Guardião. Você me concedeu nova Força."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "O que eu vi é a Prova de Existência da existência imortal do Reino Divino!"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "O processo pareceu um pouco estranho... mas acabou sendo um resultado decente, eu acho."
  },
  AvgCommunicate_134115_Content_2 = {
    Text = "O que você vê?"
  },
  AvgCommunicate_134115_Content_3 = {
    Text = "O Reino Divino... Sim... O contorno do Reino Divino!"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Nunca foi tão claro... Nunca foi tão... comum..."
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Miryam... Tem certeza de que essas são suas próprias palavras..."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Eu vejo minha terra natal. Eu vejo aquele futuro imortal, imperecível."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Mas mais do que isso... eu vejo o presente."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Meu Senhor, meus irmãos, meu Amigo próximo, meus fiéis..."
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "O Reino Divino sempre esteve ao meu lado... Tudo o que tenho sempre foi parte do Reino Divino..."
  },
  AvgCommunicate_134115_Option_10 = {
    Text = "Isso é verdadeiramente inspirador!"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Suponho que funciona..."
  },
  AvgCommunicate_134115_Option_2 = {Text = "O que?"},
  AvgCommunicate_134115_Option_5 = {Text = "Comum?"},
  AvgCommunicate_134116_Content_1 = {
    Text = "Meu Deus, nunca esperei que levar a minha Força ao seu limite máximo fosse assim."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Hm..."},
  AvgCommunicate_134116_Content_11 = {
    Text = "Hmm, deixe-me ver... Agora mesmo você está pensando: \"Sinceramente, não sei qual dos dois é mais aterrorizante.\" Estou certa?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "O quê?!! Você não disse que não consegue ler minha mente?"
  },
  AvgCommunicate_134116_Content_13 = {
    Text = "Que reação adorável. Eu não li sua mente de forma alguma."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "Apenas acontece que você fica tão completamente desprotegido perto de mim—você é só um pouquinho fácil demais de ler."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "Quer manter os pequenos segredos do seu coração a salvo? Então se esforce um pouco mais quando conversar comigo."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "Como é que é? Tenho um mau pressentimento sobre isto..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "Como hei de dizer... Basicamente, aquelas mentes medíocres são como diários abertos para mim — aborrecidos e expostos num relance. É bastante tedioso, na verdade."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "O quê?! Já dominaste a Leitura de mentes?"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "Não é assim tão dramático. Afinal, ainda há bastantes pessoas neste mundo com espíritos resilientes e personalidades teimosas que tentam envolver o seu interior em camada após camada, recusando-se a deixar que outros as decifrem facilmente."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "E depois há seres como tu, que sempre foram enigmáticos e inescrutáveis."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Não precisas de ficar nervoso. Obter as respostas de um exame antecipadamente é tão aborrecido como saber o final de uma história de antemão, ou descobrir o culpado de um caso de homicídio cedo demais."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Eu aprecio profundamente o processo de guiar, especular e descascar as Crisálidas enroladas ao redor do coração, fio por fio."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Sem esses jogos de vai e vem, como eu seria diferente daqueles charlatães que fazem diagnósticos grosseiros e simplesmente cortam um pedaço do cérebro de alguém?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Hm..."},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Como é que é?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "O que?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "As rimas dos versos tornaram-se ainda mais persistentes."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Posso levar-te ao mundo da poesia, para vaguearmos juntos."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "Isso é quase tão incrível como magia de palavras!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Então quero experimentar uma Miragem de reforma, ficar rico e comida gourmet ilimitada. Podes levar-me lá?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Isso... deve ser, sim, é possível! Por favor, dá-me um momento, preciso de pensar bem no assunto..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Agora, consigo ver as emoções a brotar dentro daqueles ritmos entoados, a Força refletida por detrás daquelas Imagens."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Não compreendo totalmente, mas parece uma visão bonita."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Sim, a poesia é uma chave para explorar a beleza. A poesia pode revelar as leis universais do mundo e espelhar a vida tal como ela verdadeiramente é."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "Na poesia, encontramo-nos a nós mesmos, encontramos a sabedoria da História e da filosofia, encontramos um santuário puro para o espírito."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ah, deixei-me levar a falar sozinha outra vez. Peço imensa desculpa..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Não faz mal. Adoro como ficas apaixonada quando falas sobre poesia. É muito encantador!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "O-obrigada, Guardião. De qualquer forma, agora consigo usar versos para pedir emprestada ainda mais Força daquele mundo, criando uma Miragem poética completa."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Quer deseje desfrutar de tranquilidade, paixão ou melancolia, quer queira perseguir o aroma das flores, as correntes do oceano ou as nuvens."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "É quase como magia de palavras."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Isso parece bonito."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "É suportável."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Você realmente ofereceu algo tão precioso para esta aqui, você..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Mas você realmente consegue comer tudo isso? Um chef reclamou antes que você limpou todo o estoque de manteiga e queijo, e eu tive que pagar do meu próprio bolso para reabastecer a cantina."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Oh? Quem anda fofocando pelas minhas costas? É melhor eu não pegá-los!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "Quanto aos bolos, cuide da sua vida sobre os assuntos de uma dama! Quantos eu fizer, eu consigo comer todos!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "E se eu não conseguir terminar, você vai comer comigo!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "E—Eu também tenho que comer? Vou morrer empanturrado e engordar no auge da minha vida!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Para de reclamar. Depois de toda essa conversa, eu ainda nem mencionei sua recompensa. Esta dama será graciosa o suficiente para guardar uma porção de cada bolo que eu fizer de agora em diante."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Seja grato! Estas são obras-primas de uma confeiteira genial que dinheiro nenhum pode comprar!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Então... essa confeitaria no final é só produção própria e consumo próprio!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, nada mal."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Agora esta dama consegue girar dez—não, cem Marchadores de Mares como piões de uma vez! Eu não preciso mais que ninguém me salve!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "A grande dama é poderosa!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Embora minha vida agora não exija preocupação constante, quando se trata de Força, quanto mais, melhor para a sensação de segurança."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Quem tem os punhos maiores nunca sai perdendo!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Mas usar uma Força tão incrível Apenas para trabalhar na Misaq é um desperdício... Já sei!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Já que tantos tentáculos podem trabalhar independentemente, é melhor eu abrir minha própria confeitaria. Com eu sozinha preenchendo oito funções, isso não significaria liberdade ilimitada de bolos para sempre!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Você pode usá-los assim?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Eu também tenho que comer?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "Então..."},
  AvgCommunicate_134118_Option_4 = {
    Text = "Murphy é poderosa!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Você pode usá-los assim?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahahaha... Ahahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Diante de poder absoluto, a conquista é Apenas um longo jogo."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "O que te fizer feliz..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "O tempo lhe trará notícias do meu triunfo. Quando esse dia chegar, como o principal contribuinte do meu novo reino, reservarei a terra mais fértil como seu feudo."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Ou... preferiria esta cidade poeirenta de Londinium?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Você não foi enlouquecida por toda aquela Força e de repente perdeu o juízo, né?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph hmph, como minha maior \"Dedicação\" de Força, posso perdoar sua pequena impudência."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah... o momento que tanto aguardei, esse sabor doce e familiar, essa sensação de Sangue fervendo nas veias!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Agora posso erguer icebergs sem esforço e fender as profundezas do oceano."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Nenhum Líder de qualquer tribo, nenhum guerreiro mais poderoso dos Marchadores de Mares duraria um único combate contra mim, e aquela mulher louca também não pode mais me suprimir."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Em breve, conquistarei os mares, e depois conquistarei todas as terras! Hahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...Confiança é algo bom, mas não seja tão narcisista! Isso já está no nível de Sintoma: Delírio!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Você não sabe nada sobre a Força de uma gigante, pequenino."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "O que te fizer feliz..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Você perdeu o juízo?"
  },
  AvgCommunicate_134119_Option_8 = {Text = "..."},
  AvgCommunicate_134120_Content_1 = {
    Text = "Minha voz ao cantar... está diferente de antes."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, vou fazê-lo!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Por falar nisso, Guardião, graças ao teu encorajamento antes, aceitei a colaboração com a editora musical. Agora o primeiro álbum foi oficialmente lançado, e ouvi dizer que está a vender bastante bem."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "Que ótima notícia! Parabéns! Quantas cópias vendidas?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Acho que... cerca de cem mil cópias. Mas eu não preciso realmente da moeda deste planeta. Como não há outra forma de te retribuir, por que não te dou os ganhos do álbum?"
  },
  AvgCommunicate_134120_Content_14 = {Text = "Yay!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Guardião, depois que você me ajudou a compreender a Regra Final, minha voz ao cantar parece ter alcançado uma Ressonância maravilhosa com o Éter."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Parece que ficaste mais forte. Faint certamente também ficará feliz!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Como poderei algum dia retribuir-te, Guardião? Poder ter um Reencontro com a minha irmã já foi uma felicidade que o meu eu do passado nunca poderia ter sonhado, e ainda assim deste-me um tesouro tão precioso além disso."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "Não tenho nada em meu nome agora, e já não sou uma estrela adorada pelos fãs. A única forma de te retribuir é... por favor, deixa-me cantar uma canção para ti."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinct, já encontraste o teu próprio Caminho. Se estiveres disposta a realizar o meu desejo..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Por favor, canta livremente, para ti mesma, e para mim."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Não para agradar a ninguém, não para atuar de acordo com as exigências de ninguém, Apenas para a tua própria felicidade."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "A minha própria... felicidade."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Que ótima notícia."
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "Isso é maravilhoso."
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "Já alguma vez pensaste em"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "O vento enche as velas, e pássaros voam em formação ao nosso lado..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Eu quero navegar pelos mares para todo o sempre, junto com você, com o Capitão, com todos."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Experienciar dias ensolarados e dias chuvosos juntos, navegar para todos os tipos de portos, atracar em diferentes países."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Pescar juntos, grelhar peixes juntos... Ah, e poderíamos raspar mexilhões do casco e cozinhá-los em vinho tinto."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Vamos para as próximas férias."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Eu pensei sobre isso por muito tempo. Navegar... é quando eu sou mais feliz."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Eu vou guiar todos para longe de cada tempestade, para que possamos continuar navegando felizes juntos."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Parece maravilhoso, mas se navegássemos sem parar para sempre, todos, exceto os Corpos Despertos do Mar Profundo · Domínio, ficariam enjoados!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Eu vejo a proa cortando as ondas, eu ouço os Marinheiros cantando suas canções marítimas, eu sinto os sussurros do vento e da chuva."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Eu consigo ver com mais clareza agora — o curso que leva a águas claras e de Tranquilidade."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Parabéns! Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Agora, talvez eu possa realmente realizar os desejos de todos e guiar os navios sob minha proteção em segurança até a outra margem."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Eu não vou decepcionar todos de novo."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "Então, e quanto ao seu desejo? Você já decidiu o seu desejo?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Meu desejo..."
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "Eu já decidi."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Vamos para as próximas férias."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Isso parece maravilhoso."
  },
  AvgCommunicate_134180_Option_4 = {Text = "Parabéns"},
  AvgCommunicate_134180_Option_7 = {
    Text = "E quanto a você?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah... O Chamar do oceano, tão gentil, tão caloroso."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "O comportamento bruto do Rogers deixou uma sombra tão grande em você, ou você acha que sou uma artista tão estéril e preguiçosa?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Aprimorar o ofício não permite atalhos. Minhas esculturas são naturalmente esculpidas pelas minhas próprias mãos, golpe de cinzel por golpe de cinzel."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Fique tranquilo, não usarei sequer um único fio do seu Cabelo."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Haha... Talvez seja porque suas habilidades de escultura são boas demais. Toda vez que vejo suas obras, tenho a ilusão de que estou olhando para uma pessoa viva."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Bem, agora que minha Força atingiu seu auge, talvez eu realmente consiga criar uma escultura que ganhe vida."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "Na calada da noite, além do seu campo de visão, os olhos da escultura se virariam lentamente, e os cantos de sua boca se curvariam levemente..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Assim que eu terminar minha obra mais recente, colocarei uma bem ao lado da sua cama para vigiar você em meu nome. O que acha?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Eu nunca mais ousaria dormir pelo resto da minha vida!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Eu estava só te provocando."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Parece que você realmente fica apavorada com histórias de fantasma tão simples. Que adorável."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Certamente você também ouviu?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Está nos convidando, estão nos esperando... para viajarmos juntos ao palácio branco e puro sob o mar."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Quem? Receio que meus ouvidos ficaram surdos — não ouvi absolutamente nada."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Então este deve ser um Beijo da Musa destinado Apenas a mim. A beleza do oceano agora se fundiu com a minha própria alma."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Você sempre me traz mais Discernimento para as minhas criações. Eu realmente gosto mais de você a cada dia."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Você consideraria se tornar meu assistente permanente? Não precisaria fazer nada — apenas venha ao meu ateliê todos os dias, sente-se um pouco, tome uma xícara de chá e converse."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Embora eu me sinta honrado pelo seu afeto... vou acordar uma manhã e me ver transformado em uma escultura de pedra?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Hehe, é assim que você realmente me vê?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Sua habilidade artesanal é incrível."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "Não, por favor!!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "Eu não ouvi."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Vou ser transformado em uma escultura?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Cachorrinho, como você tem passado ultimamente?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Não aja precipitadamente. Não importa o que aconteça, o Lago Negro vai mantê-lo firmemente aprisionado."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Você não tem a menor ideia de que tipo de Força o conhecimento pode me conceder."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Estou muito satisfeita com este presente. Então, meu querido estudante, eu lhe darei um presente em troca."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Adivinhe. Adivinhe até onde eu posso ir agora."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Adivinhe se suas arrogantes medidas de contenção realmente podem surtir efeito."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Adivinhe se a Verdade que eu espiei será, agora que obtive esta Força, implantada na cognição de Todos."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Este é o dever de casa mais importante, sabia? Em breve, muito em breve, virei pessoalmente para corrigi-lo."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Sua audácia realmente me surpreende — você realmente ousou enviar um presente desse calibre."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Você acreditaria se eu dissesse que houve um acidente grave durante o transporte de materiais raros..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Você me subestima, e subestima a Misaq."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Estamos dispostos a deixar cada Corpo Desperto tocar esse limite, porque tentaremos todos os métodos para prevenir a Sintoma: Destruição."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Isso é... a maior diferença entre aquela professora Doll, e nós, e você. Mesmo que a Sintoma: Destruição seja inevitável, nunca nos submeteremos a ela."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Suspiro, como eu não descobri antes que o sistema educacional da Misaq poderia produzir tolos assim."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Felizmente, um tolo tão lamentavelmente estúpido que é difícil não sentir afeição por ele."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Foi um acidente."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "É minha intenção sincera."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Regras, tão fixe! Bang—! Boom—! Kaboom—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Nesse caso, os custos de reparação da escola devem diminuir significativamente este mês..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Trabalho de casa mau, aparece, Mosk, esmaga morto!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Não, você não pode contar o dever de casa como um inimigo também!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Mosk, Mosk?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Guardião, aqui é a Nautila. Fique tranquilo, o Mosk foi contido. O dever de casa e a sala de aula estão seguros."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Graças a Deus..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, a Misaq, o Mosk e eu sempre precisaremos de você."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Lembra-te da Regra N.º 1 do Código Misaq, Edição Especial Mosk: Sob nenhuma circunstância é permitido apontar qualquer arma letal a alguém em Misaq."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, não te preocupes, Mosk, controlo, consegue!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Mosk, controlo, vórtice."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Mosk, amigo, abracinhos."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Mosk, inimigo, bang—! boom—! kaboom—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Segurança em Primeiro Lugar."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Somos companheiros de armas, então não vou dizer obrigado."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "A minha arma foi afiada até ao seu limite mais cortante — afiada o suficiente para cortar a garganta de um senhor de escravos num instante."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "O significado da resistência, o significado da vingança, o significado da batalha — ainda os pondero incessantemente."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Talvez continue a ponderá-los pelo resto da minha vida, até ao dia em que já não consiga ficar de pé."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "No mínimo, já não estou perdido."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Aos meus companheiros de armas."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Aos companheiros de armas. Foste tu que me libertaste e me deste a vontade Resiliente para continuar."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Sempre que precisares de mim, estarei sempre a cobrir-te as costas, a Lutar lado a lado contigo."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Vamos continuar a lutar juntos — pela vingança que tem de ser consumada, e pela emoção da própria batalha."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Aos companheiros de armas."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Guardião, enviei um pedido ao Departamento de Assuntos Acadêmicos. Estarei ausente do treinamento nos próximos três dias."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Mas depois que ultrapassei aquele limite, eu compreendi."
  },
  AvgCommunicate_134201_Content_11 = {Text = "O que?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Eu sou a lâmina da vanguarda. É precisamente porque sempre trilhei este Caminho que pude conhecer todos vocês, e conhecer você."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Minha busca garante que eu nunca esteja sozinha. Talvez nunca cheguemos lá, mas Apenas perseveremos, e eu posso trazer aquele mundo ideal e justo um pouco mais perto, e mais perto ainda."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Com meu corpo como lâmina, até alcançarmos a utopia onde Todos possam viver na luz."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Que visão grandiosa, Instrutora Alva! Vou apoiá-la incondicionalmente!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Maravilhoso. Nesse caso, usarei estes três dias para desenvolver um regime de treinamento ainda mais rigoroso e exigente."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Você será o primeiro a experimentá-lo. Fique tranquilo, eu o acompanharei durante todo o treinamento e melhorarei junto com todos."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Espere, acho que podemos discutir isso um pouco mais..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Houve algum problema com os materiais? Você está bem? Precisa de ajuda?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Não, muito pelo contrário. Tudo correu perfeitamente. Eu tive um avanço diferente de qualquer outro anterior."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Eu não entendo muito bem..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Eu... depois de deixar o exército, vaguei por muito tempo."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Eu não sabia pelo que deveria lutar. A única coisa que podia seguir era um senso de justiça que eu nem tinha certeza se conseguiria alcançar no final."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Eu queria ficar do lado dos fracos, do lado daqueles que não podem se manifestar, do lado daqueles tratados injustamente."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Mas eu também sabia muito bem que, não importa o quão forte eu me tornasse, sempre haveria coisas diante das quais eu seria impotente — assim como, mesmo que o tempo fosse revertido, eu ainda não poderia impedir a queda de Aran."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Instrutora Alva..."
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "O que aconteceu?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Obrigada por me confiar algo tão precioso, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Acho que ele pode estar me dizendo que, além de deixar sombras na memória, o mundo também pode ser medido por passos."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Se não consigo reter as lembranças, então vou continuar avançando, sempre em frente. O mundo e todos vocês vão lembrar por mim."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Até eu não consigo deixar de me sentir empolgada..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Vou me tornar a maior exploradora, a mais incrível mestra mecânica. %player%, quero formalmente estender o Convite a você."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Quando chegar o dia em que tudo estiver resolvido, por favor, vá em uma aventura comigo. Vamos criar mais memórias preciosas neste mundo."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Talvez esse dia esteja distante, ou talvez seja amanhã."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Este convite é válido para sempre. Eu vou lembrar dele, eu prometo."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Passei muito, muito tempo absorvendo tudo... Agora sinto como se tivesse me tornado completa novamente."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Então, isso significa que você não vai mais esquecer as coisas?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, deixe-me pensar..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, ainda não consigo lembrar das coisas!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Por que você parece tão orgulhosa disso!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Porque, mesmo que eu ainda esqueça muitas coisas, no passado e agora, %player% sempre estará lá para me lembrar e me ajudar a recordar."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Quem eu sou, onde estou, o que preciso fazer — as pessoas em quem mais confio vão me dizer."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Talvez seja por isso que, após compreender a Regra Final, mesmo que minha memória não tenha melhorado, sinto como se o mundo inteiro tivesse se desdobrado diante dos meus olhos como um vasto mapa."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Sua memória melhorou?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Eu antes acreditava que Apenas desempenhando o papel de Público eu poderia experimentar a alegria do desconhecido."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Não entendo completamente... mas parece que deveria ser algo bom?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Desde que parti daquela porta, esta é a maior bênção que encontrei."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Guardião, esta é a surpresa que você me deu—uma que eu jamais poderia ter previsto."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "O Destino nunca falha com aqueles que dão generosamente."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Não posso tocar seus fios, mas enquanto você luta pelo Destino, minha roda de fiar girará para sempre por você."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Faz muito, muito tempo desde a última vez que experimentei essa sensação..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Como é que é?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Novidade."},
  AvgCommunicate_134208_Content_5 = {
    Text = "O desabrochar silencioso dos botões, o entrelaçar de palavras sobre o papel, o suave flutuar das nuvens no vento..."
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "E claro, as pessoas—aqueles braços estendidos, aquelas lágrimas caindo, aquelas batidas do coração como tambores de guerra ou gotas de chuva..."
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Vejo mais do que antes, mas meus olhos estão mais baixos do que costumavam estar."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Eles já não permanecem no céu, Guardião. Desceram, pousando em cada rua, ao lado de cada passante."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Agora, não preciso desempenhar um papel. Posso verdadeiramente existir como um indivíduo."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Isso parece ser algo bom?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Como é que é?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Texto temporário"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Parece ser algo muito valioso, não há problema em dar para Saya?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Então este mundo também tem seu lado belo, embora seja um pouco diferente do mundo que guardo na memória."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "A forma como é constituído, a lógica de seu funcionamento — Saya já consegue compreender tudo completamente."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Portanto, reescrever este mundo para que se torne aquele que guardo na memória, talvez eu seja capaz de fazer isso com muita facilidade agora."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Embora eu saiba que você está brincando, por favor não faça tal coisa de jeito nenhum."
  },
  AvgCommunicate_134245_Content_17 = {Text = "..."},
  AvgCommunicate_134245_Content_18 = {
    Text = "Por que ficou em silêncio? Estava brincando, certo? Não fique em silêncio num momento desses!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Bem, há pouco eu só saí por um momento e observei a todos de uma nova perspectiva..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Eu confio em Saya, então não há problema."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Enquanto todos que conheço e que tratam Saya com gentileza ainda estão bem e vivos, é assim."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Não consigo dizer o que está errado, mas tenho a estranha sensação de que algo definitivamente não está certo."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "E agora você certamente está com aquela expressão de quem pregou uma peça com sucesso!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Não se preocupe, vou conviver bem com todos neste mundo."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Hmm... mas o mundo na memória de Saya pode ser ainda mais interessante. Que tal irmos todos dar uma olhada? Agora deve ser possível!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Essa frase é ainda mais assustadora!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Se puder te ajudar a entender melhor este mundo, também deve ser de grande ajuda para a pesquisa sobre \"como deter a Dissolução\"."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Afinal, você é realmente muito forte em aprendizado e pesquisa..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "Na verdade, foi um acidente com alguns suprimentos... mas agora já deve ser tarde demais para se arrepender?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Hã? Então devo devolver? Estou um pouco indecisa."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Hein? Posso devolver?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, deixa Saya pensar..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "A resposta é — não."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Sem problemas"
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "Foi um acidente"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Meu querido, amado, magnífico benfeitor~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Deixa eu verificar."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Deixa eu verificar os dados de flutuação do seu Índice Gnóstico."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Olha só — nossa Caraboo realmente não mentiu desta vez."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Heh heh, agora acredita na pobrezinha da Caraboo, não é?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Por favor, continue investindo generosamente em mim — Para que eu possa render ao meu querido benfeitor cem, mil vezes mais lá na frente!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Só mais oito — não, cinco Fragmentos de Despertar Espiritual! E vou impressioná-lo novamente, prometo!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Isso é impossível."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Boa tentativa."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "A Professora Doll me disse que a pesquisa sobre o Despertar Espiritual dos Corpos Despertos já atingiu seu limite. Não haverá outro avanço por um século."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Uma vez que um Corpo Desperto alcança o Axioma Absoluto, ele nunca mais pode passar pelo ritual de Surto Psíquico."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "O que você precisa desta vez, aparecendo assim tão lisonjeiro de repente?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha — devo ter confundido alguma coisa sem querer!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Por favor, rebobine sua memória desta conversa em seis mensagens. Tenha um ótimo dia~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Ora, ouça você — o que acha que sou, alguém que só aparece quando quer algo?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "É exatamente isso que você é..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Buá, estou de coração partido. Meu benfeitor me julga tão mal."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "Na verdade, vim trazer boas notícias desta vez!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Seu investimento deu frutos — com resultados super, super incríveis~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Viu? Sou uma pessoa completamente nova. Renascida, transformada, totalmente diferente~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Sério?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Deixa eu verificar."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Isso é impossível."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Boa tentativa."
  },
  AvgCommunicate_134246_Option_9 = {Text = "Sério?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Texto temporário"
  },
  AvgCommunicate_134249_Content_1 = {
    Text = "Guardião..."
  },
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm... Aquela sensação voltou de novo. De repente estou com calor, e com sede. Meu estômago, Dentro do meu estômago,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Guardião, estou doente? Meu estômago está amolecendo, meu coração está amolecendo, tudo está mole. Não consigo distingui-los, é como se eu estivesse derretendo..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Respire fundo, Leigh. Você não vai derreter."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Isso é uma reação humana normal em relacionamentos íntimos. Não precisa de remédio... e também não precisa pegar um chicote!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Hã? Nem um chicote? Que decepção."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "...Ah, se você realmente precisa de um, talvez vá pedir à Pandia..."
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hehe..."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Guardião, vou tentar não ficar mais agachada do lado de fora da sua Porta."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Mas... você poderia ocasionalmente deixar uma Porta aberta para mim à noite? Uma janela também serviria."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "A Carne e sangue do irmão e meu corpo estão mais compatíveis do que antes. Elas respiram silenciosamente sob minha pele, sem mais gritar constantemente para me despedaçar."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Não vou entrar Dentro. Apenas saber que há um Caminho que leva até você a qualquer momento me ajudaria a dormir mais tranquilamente."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "O desejo por Sangue também não dói tanto. Antes, era como algo preso na garganta—asfixia se eu não bebesse. Agora parece... disposto a esperar um pouco por mim."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Isso é uma ótima notícia."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "As noites na escola são tão silenciosas. A fonte respinga suavemente."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Guardião, você me deu tantos tesouros. Eu realmente os mereço?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Claro que merece."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Você sempre responde tão rápido."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, você nos ajudou imensamente. É o mínimo que posso fazer."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Você não sabe como termina quando se cria uma fera selvagem?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Muitas vezes me pergunto se você é realmente como aparenta ser na superfície, ou..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "Na verdade, você esteve fingindo o tempo todo, assim como aqueles mestres de escravos."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "O que você acha? Não sou boa em atuar, nem sou boa em mentir."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Pode seguir seus próprios sentimentos. Não vou tentar te convencer, nem vou te forçar a fazer nada."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Apenas como a outra você disse uma vez, somos amigos—companheiros de armas."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, não me coloque no mesmo grupo que aquela fracote."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Já estou farta de traição há muito tempo. Não preciso de amigos."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Além disso, também não quero nenhuma das suas promessas."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Apenas me forneça mais Força, isso é suficiente."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "E eu me vingarei dos seus inimigos por você em troca."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Uma fera que cresceu arrebenta suas correntes e—rawr—morde a garganta de seu dono."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Até o dia em que você verdadeiramente me trair... Mesmo que fuja para os confins da terra, eu vou te caçar e arrancar sua garganta."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Agora mesmo, seu Link comigo parece mais Frágil do que correntes de ferro aos meus olhos."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Você não tem medo?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Você é livre. Nosso Link não foi feito para restringir você."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Não tenho razão para ter medo."
  },
  AvgCommunicate_134250_Content_7 = {Text = "..."},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, palavras doces."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Mas eu tenho observado você por tanto tempo, e ainda não Descobri um momento em que você tenha uma Vulnerabilidade."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "O que você acha?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "Você é livre"
  },
  AvgCommunicate_134263_Content_1 = {
    Text = "Guardião!!"
  },
  AvgCommunicate_134263_Content_10 = {
    Text = "Claro. Nunca duvidei que você ficaria mais forte."
  },
  AvgCommunicate_134263_Content_11 = {Text = "..."},
  AvgCommunicate_134263_Content_12 = {
    Text = "Você é realmente uma pessoa estranha."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "Num momento como este, não devias dizer algo como \"Vês, eu sabia que tinha bom olho para ti\" ou \"Correspondeste mesmo às minhas expectativas\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Por que estás tão calmo com isto?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Uh...porque te esforçaste tanto, ficar mais forte é apenas natural. O que há para dizer?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "As 50 pratas que me pagaste no ano retrasado, e as 54 pratas do ano passado—guardei todas."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Para quê guardar...gasta-as."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Esquece, deixa isso. Há algo importante."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Aqueles padrões estão esquentando. A Força do Mar Profundo está fluindo sob minha pele, muito mais claramente do que antes!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Vai ao lago agora mesmo. Estou à tua espera aqui."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "Qual é o problema?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Vais descobrir quando chegares."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Está bem...então espera um pouco por mim. Está a chover lá fora agora. Preciso de voltar ao dormitório e pegar num guarda-chuva primeiro."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Para de enrolar. Não vamos precisar de guarda-chuva para o que vem a seguir."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Não vais apanhar chuva. As minhas asas membranosas são grandes o suficiente."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Você tem ideia do que isso significa?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "Enfim, é incrivelmente incrível, além das palavras. Vocês humanos provavelmente não conseguem compreender."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "...Caecus, você está bem?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Claro que estou bem. Nunca estive melhor."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Eu te disse há muito tempo, seu investimento não seria desperdiçado. Meu Sangue nunca mente para mim."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Eu sei."},
  AvgCommunicate_134263_Content_9 = {
    Text = "...Só isso?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Por favor, me perdoe, Mensageiro Pálido. Eu não estava preparado para isso e parece que te assustei."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Apenas penso nisso, a paz no meu coração supera em muito o sofrimento da minha carne."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Eu entendo. Talvez não tenha ideais tão grandiosos. Mas mesmo que seja por ti, pelos meus amigos."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Apenas eu consiga alcançar esse mundo ideal e pacífico, não importa o que custe, darei o meu melhor."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Obrigado, Mensageiro Pálido."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Que todo o sofrimento encontre o seu dia de dissolução, e que tu e eu caminhemos sempre lado a lado."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Que a proteção do Pai Deus também desça sobre tudo o que te é querido."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Ufa... Ainda bem que estás bem. Não esperava que a compreensão das leis trouxesse este tipo de Efeito."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Não te preocupes comigo. Esta é a própria missão para a qual vim a este mundo."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Antes de cruzar o limiar do auge, antes de o Pai Deus me revelar estes mistérios insondáveis, eu já me havia dedicado a este Caminho."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Reunir o sofrimento de todos os seres sobre mim, guiando todas as coisas rumo a uma terra imaculada onde o sofrimento já não existe— isto não é um fardo. Esta é a graça que o Pai Deus me concedeu."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Sempre senti que carregas demasiado. A dor dos outros é Dissolvida, mas o custo..."
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Minha chama pálida, possuis um coração terno."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Mas fica tranquilo. O sofrimento físico é para mim como os espinhos são para o solo— quanto mais fundo penetram, mais firmemente eu Enraízo."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Se ainda uma só alma neste mundo sofrer, ela jamais sofrerá sozinha. Se ainda uma só não tiver escapado do mar de sofrimento, eu jamais alcançarei a outra margem antes dela."
  },
  AvgCommunicate_134264_Option_11 = {Text = "Eu entendo"},
  AvgCommunicate_134264_Option_6 = {Text = "Mas..."},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, estimulante, absolutamente estimulante!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Pergunte a qualquer um dos meus rapazes — eles me conhecem há anos. Quando é que me viram fazer algo assim!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, agora que minha Força está ainda mais feroz, vou ter que tomar cuidado pra não te queimar da próxima vez."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "O quê... foi você? Então, aquelas vezes que minhas roupas foram trocadas... também foi você?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Sim, suas roupas estavam todas sujas de bebida e comida. Eu não podia simplesmente deixar você se enfiar na cama daquele jeito."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Obrigada, Katie Gula."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Mas da próxima vez, você poderia apenas me sacudir pra acordar..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Oh, ficando tímida? Não se preocupe com isso — olha como somos próximas."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Deixa pra lá algo tão trivial como trocar de roupa — mesmo que me pedisse pra atravessar fogo ou escalar uma montanha de lâminas, não seria problema nenhum!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Na pior das hipóteses, da próxima vez deixo você me ajudar a trocar de roupa. Justo, não é?"
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Nada disso é razoável, e é tão absurdo que eu nem sei como responder!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Uma sensação de euforia sem precedentes — agora, eu sou o sol!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Pequenina, estou cada vez mais impressionada contigo."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Apenas percebeu isso agora? Ainda há muito mais de onde isso veio."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? Parece que todas nós te tratarmos como uma pequenina não tem sido muito apropriado."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... de agora em diante, devo Começar a te chamar de grandona."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "Grandona? Que tipo de nome é esse! Está zombando de mim de novo com essa cara séria, não é?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, não tem como evitar. Você é sempre a primeira a apagar toda vez que saímos pra beber."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Então eu tenho que te carregar de volta pro dormitório toda vez, tirar seus sapatos, te cobrir e limpar seu rosto."
  },
  AvgCommunicate_134265_Option_12 = {Text = "Foi você?"},
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, minha música se tornou ainda mais perfeita."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Minha música era como uma máquina funcionando com precisão, e isso uma vez me garantiu um lugar na orquestra mais prestigiada. Claro, eu tinha orgulho disso."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Ele era diferente. Ele não era adequado para ensemble. Sua música foi feita para brilhar sozinha no céu, como o sol ou a lua."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Eu sempre o observava, perseguindo-o. Apenas que eu já havia perdido para sempre a chance de me comunicar com ele."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Mas... a apresentação que agora alcançou a perfeição suprema é provavelmente a melhor resposta que posso apresentar após uma vida inteira de busca."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Isso é tão comovente... Como você tem um passado assim? Uma história lendária de músicos brilhando intensamente e refletindo a luz um do outro..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, Apenas algumas reflexões perfeitamente comuns. Realmente não é nada tão dramático."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "De qualquer forma, o que eu mais quero dizer é: obrigado, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "De agora em diante, por favor, permita-me continuar a Disparar minha flauta para você, acompanhando-o em um sono tranquilo a cada noite."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Sem a sua orientação, eu provavelmente nunca teria conseguido dar este passo final — calibrar os erros mínimos que antes estavam além da capacidade humana de corrigir."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Ritmo perfeito, afinação impecável, tudo soa tão primoroso..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "De fato! Eu nunca ouvi uma apresentação tão encantadora!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Este é o resultado da Ressonância entre música e cálculo, instrumento e corpo, mente e músculo."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Eu finalmente provei que no final deste Caminho árido e tedioso, uma música tão perfeita também pode existir."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Também? O que você quer dizer com isso?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "No passado, eu tive Uma amigo cuja música era o produto da mais extrema sensibilidade e criatividade."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "O talento que ele empregava tão livremente permitia-lhe improvisar composições únicas a cada apresentação."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Waaah..."},
  AvgCommunicate_134267_Option_4 = {Text = "De fato"},
  AvgCommunicate_134267_Option_7 = {
    Text = "Além disso?"
  },
  AvgCommunicate_134268_Content_1 = {
    Text = "Meu mais honrado convidado, como poderei algum dia agradecer por sua generosidade?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Entendo, compreendo. Você não quer aquelas celebrações vulgares. Eu também acredito que não combinam com você."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Ainda há uma boa ideia. Talvez você esteja disposta a tentar me acompanhar para além da Necrópole para receber alguém que se aproxima do seu fim?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Se nos for concedida tal honra, espero que você e eu possamos recebê-Lo juntos, guiando-O até o Seu destino final e novo nascido curado. O que acha?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Embora possa ser um pouco inoportuno perguntar... Imagino que no final ainda envolverá consumo, já que esse é o costume da Necrópole."
