  AvgCommunicate_134268_Content_17 = {
    Text = "Claro, claro."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Então, a carruagem da Necrópole e eu estaremos esperando pela sua chegada do lado de fora da Porta amanhã de manhã."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Seu presente me concedeu a Força para verdadeira e firmemente servir como Guardião da Necrópole."
