  AvgCommunicate_134268_Content_4 = {
    Text = "Que dilema deliciosamente vexatório."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Você é muito gentil, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Já passamos por tanta coisa juntos. Você realmente não precisa se preocupar com essas formalidades tediosas do Trânsito."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh não, não, isso de forma alguma é uma mera formalidade. Estou sinceramente contemplando como organizar um encontro com uma querida amiga."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Você já testemunhou a mais extraordinária Dança da Necrópole. Como aprofundar ainda mais o vínculo entre você e nós — isso é de fato um desafio."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Hm... Se quer saber a minha preferência, humildemente espero que seja algo comum, sem nenhum susto..."
