  AvgCommunicate_134268_Option_9 = {Text = "Um"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Minha pequena muda..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "Dentro do meu corpo, a Força da \"Reprodução\" está florescendo, nascida do toque com o absoluto."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Que doce, que exuberante... Ah, estou cansada de falar com você através deste pequeno bloco de metal."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Venha ao meu lado, pequena muda. Agora, neste instante."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Quero segurar as tuas palmas quentes, tocar a tua pele suave..."
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Quero abraçar-te sob o luar, tal como na noite em que fizemos a nossa promessa."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Com a minha Força cada vez mais abundante, fundindo-me contigo pouco a pouco, e deixando a tua doce essência aquecer-me, aos poucos..."
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "O que você me prometeu — nosso pacto feito sob o luar e através do mar de areia — você já começou a cumpri-lo por mim."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Estou tão feliz."
  },
  AvgCommunicate_134269_Content_4 = {
