  AvgCommunicate_134277_Content_11 = {Text = "..."},
  AvgCommunicate_134277_Content_12 = {
    Text = "Uau, quem de nós é mais louco aqui? Por uma razão dessas, você entregaria esse nível de Força a uma lunática como eu?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Será que a minha vinda a este mundo foi realmente um arranjo do Destino?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "De qualquer forma, graças a você, eu toquei o que me pertence no seu mundo — o meu \"limite.\""
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Agora então, rápido, me atribua uma missão! Mal posso esperar para ir cortar algumas cabeças e mostrar do que sou capaz～"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Uma garota presa em um mundo estranho recebe um presente caro que pode torná-la mais forte. Você sabe com o que esse tipo de coisa se parece?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Antes que você diga algo que desvie dos processos normais de pensamento humano, deixe-me dizer primeiro — você é membro da Misaq. Nós nos ajudamos. É por isso que dei aqueles materiais a você."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Sério? Não é algum comportamento humano socializado entediante e indireto de fachada?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "\"Ela não pode voltar para casa, que pena, vamos mostrar um pouco mais de cuidado.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"Deve ser tão difícil descobrir as coisas sozinha, vamos dar uma ajudinha.\" Não é realmente uma daquelas razões de alta frequência que você encontraria numa sociedade comum?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Primeiro de tudo, não importa como você olhe para isso, Mouchette, você não tem nada a ver com a palavra \"comum\"!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmph☆hmph, agora essa é uma avaliação de que eu gosto bastante."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Segundo, não importa qual seja a sua autopercepção ou como você aparenta ser na superfície, para mim, como você disse, \"Mouchette\" é \"Mouchette.\""
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Primeiro de tudo"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Obrigado, meu querido. Trouxeste-me tanta felicidade e permitiste-me manter para sempre a minha ambição."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Qualquer forma de gratidão que você desejar, eu posso torná-la realidade."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Mesmo que eu ainda não possua, mesmo que sejam as Estrelas e a lua, eu encontraria um jeito de trazê-las até você."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Qualquer coisa que eu escolher? Qualquer coisa mesmo?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Manter a palavra é um passe indispensável no mundo da fama e da fortuna."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Bem, então gostaria que a Madame me fizesse uma promessa. Quanto aos detalhes, vou precisar de mais tempo para pensar."
  },
  AvgCommunicate_134278_Content_15 = {Text = "..."},
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, que escolha astuta. Você está me fazendo gostar cada vez mais de você."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Claro, meu querido. Você tem bastante tempo para pensar nisso."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Se tiver tempo, por que não vem à minha propriedade esta noite? Talvez, quando estivermos a sós... você consiga ter uma \"boa ideia\" refrescante."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Servi-la, minha senhora, é um prazer."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, sensato, inteligente, corajoso, leal, e com o toque certo de... beleza."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Quem poderia dizer que você não é um perfeito..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Perfeito o quê?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Você parece um pouco nervoso?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Minha senhora sempre nos deixa sem palavras."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Algumas coisas não precisam ser expressas em palavras. Seus sentimentos todo esse tempo — eu recebi todos eles."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Terras, propriedades, tesouros raros, arte e a chance de conhecer tantas estrelas... com meu poder atual, tudo está ao alcance."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Mesmo, qualquer coisa?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Gostaria de uma promessa sua, Madame."
  },
  AvgCommunicate_134278_Option_2 = {Text = "Com prazer"},
  AvgCommunicate_134278_Option_5 = {Text = "Perfeito?"},
  AvgCommunicate_134278_Option_7 = {Text = "..."},
  AvgCommunicate_134279_Content_1 = {
    Text = "Guardião, você ainda está acordado?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Mas tudo o que você derramou em mim... convergiu num novo lago dentro de mim. Um ainda mais vasto do que aquele mar."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Ele me disse: não há mais necessidade de ter medo."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Eu entendo que a dor talvez nunca se dissolva por completo, mas não importa quantas vezes seja preciso, eu sempre vou te puxar de volta para a praia."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "...Se a mamãe e o papai pudessem te ouvir dizer isso, tenho certeza de que ficariam em paz."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Eu acho... que talvez eles estejam em algum lugar naquele mar, velando por quem eu sou agora."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "De agora em diante, empunharei esta Força que me foi concedida e me tornarei a maré que serve como sua Guardiã."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Talvez... você estaria disposto a atender mais um pedido ousado?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "O que é? Apenas algo que eu possa fazer, e ficarei feliz em ajudar."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Quando o céu clarear, por favor, caminhe comigo à beira-mar."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Ainda há tanta coisa que quero te contar. Apenas uma tarde é tudo o que peço."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Me desculpe se estou perturbando seu descanso..."
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Claro, sem problema. Eu prometo."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Não, ainda estou acordado. O que houve?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Depois de receber seu Presente, caí em um sono profundo e mergulhei em um Sonho. Sonhei com aquele oceano de antes, e o pôr do sol do lado de fora do Sanatório."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Mas desta vez... eu não entrei no mar."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Fiquei na praia, contemplando aquele mar. Ainda me preenchia com uma sensação de paz, mas eu não tinha desejo de avançar."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Se não for presunçoso da minha parte adivinhar — é porque, desta vez, você tinha um motivo para ficar?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Bom."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Eu fui esmagada pela dor. Nada conseguia lavar o peso alojado na minha garganta — nada exceto o oceano, que varre e abraça tudo."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea..."
  },
  AvgCommunicate_134279_Option_17 = {Text = "O que?"},
  AvgCommunicate_134279_Option_7 = {Text = "Porque..."},
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, ontem à noite, eu tive aquele sonho de novo."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Talvez tenha sido o Efeito da Regra Final."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Sim, então eu quero dizer—em nome de todos os \"24\"s, obrigado, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Obrigado por nos permitir ouvir uns aos outros, ver uns aos outros, entender uns aos outros e aceitar uns aos outros."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Isso não foi obra minha."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Não, a orientação e o conforto que você deu acalmaram todos os espíritos inquietos."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Foi a sua presença que fez todos os rios convergirem em um só."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"Eu\" — todos nós — jamais esqueceremos a sua bondade."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Eu parecia ter retornado ao sopé das montanhas nevadas do extremo norte, dentro de uma caverna escura como breu."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Incontáveis massas de limo, refletindo incontáveis sombras de \"24\"..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Aqueles... são todos você, todos uma parte de você."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Eu sei."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Em meio ao Caos, pareceu-me ouvir alguém dizer algo para mim."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "A voz era nebulosa. Não consegui distingui-la claramente..."
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Mas depois que aquela pessoa partiu, senti todo o clamor ao meu redor se acalmar."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Os sussurros ruidosos nos meus ouvidos se tornaram harmoniosos e naturais, Como se fossem uma melodia concordante..."
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Todas elas são você."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Guardião, você acredita no Destino?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...Como uma pessoa comum, mal consigo imaginar como essa sensação é incrível. Permita-me perguntar com os dentes cerrados — como é essa sensação de verdade?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Como eu descreveria? Por exemplo, estou sentindo um pouco de fome agora..."
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "? E depois?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Ah, desculpe pela espera. Alguém acabou de bater na porta — era a Srta. Mason compartilhando um bolo inglês recém-assado."
  },
  AvgCommunicate_134281_Content_14 = {Text = "¿¿¿???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Assim mesmo. E então... Estou sentindo um pouco de sede."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm? O mordomo do Sr. Doresain acabou de entregar um convite, dizendo que ele gostaria de me convidar para Aprecie sua Coleção de vinhos tintos armazenada em um restaurante próximo."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Chega. Da próxima vez, você poderia sinceramente ter vontade de me ajudar com minha lição de casa?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, como desejar, %player%. Você agora é meu maior patrono, patrocinador, parceiro e indispensável {Male=Mr.,Female=Miss} Watson."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Detetive Sortudo, muito feliz em ser útil."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Eu acredito no Destino, e acredito que possuo o Destino mais sortudo de todos."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Surpresas inesperadas, fortunas caídas do céu, bênçãos vindas do nada — quando essas coisas acontecem comigo de repente, eu nem pestanejo mais."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Quando você se acostuma com o favor do Destino, todas as surpresas agradáveis se tornam insignificantes."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "O que você acabou de dizer é realmente invejável e irritante ao mesmo tempo."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Espere, eu ainda não terminei. Conhecer você é a coisa mais sortuda entre todas as minhas fortunas."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "O que você me dá sempre traz novas surpresas."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Apenas como agora — a Força que Emergiu após compreender a Regra Final já me permite sentir claramente cada golpe de boa sorte antes de ele chegar."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Coisas sortudas caem como gotas de chuva — de uma garoa suave, whoosh — para um aguaceiro torrencial."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Como é essa sensação?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "¿¿¿???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Isso é invejável e irritante ao mesmo tempo"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Guardião."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Mas com tantas pernas, não é um pouco injusto você participar de uma corrida..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor tem asas, e Nautila também trouxe o veículo Dela."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Normalmente faço têxtil no teatro e não sou habilidosa em esportes. No entanto, já inscrevi minha Donzela."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "É difícil imaginar por que você se interessaria por algo assim?"
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Ver pessoas revelarem uma vitalidade tão vibrante e uma vontade tão tenaz na busca de um objetivo é verdadeiramente algo delicioso."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "Além disso... estou bastante curiosa sobre que tipo de magia aquele bolo oferecido como prêmio possui, para ter até mesmo Tawil tão encantado por ele."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Apenas não seja algum tipo de escolha que destrua um mundo, qualquer coisa serve..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Ahn, você não usaria os Fios do destino para manipular os resultados da competição, certo?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "Qual é o problema?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "Até logo no Público, Guardião."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Você acha... que tipo de Destino pode ser verdadeiramente considerado justo e correto?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Justo e correto?... Provavelmente proteger os interesses da maioria tanto quanto possível."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Então e se — os interesses de poucos estiverem destinados a ser Sacrificados? Você aprova essa direção do Destino, não é?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Você... por que está perguntando isso de repente? Não me entenda mal!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Se você está prestes a fazer algo como destruir algum mundo novamente, por favor, pense bem, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Não precisa se preocupar, Guardião. É Apenas uma corrida."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Ufa... você me assustou..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "Qual é o problema?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Guardião, ao saber que você viajaria para longe em uma investigação, compus especialmente uma obra para você."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Seu senso de nomenclatura é realmente algo especial, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Cada fio tecido tem seu dono predestinado. Cada história, também, tem seu leitor."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Um nome que se espalha facilmente pode ajudar essas excelentes histórias a alcançar mais das pessoas a quem são destinadas."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Por exemplo, esta obra mais vendida..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "\"Guia de Culinária com Criaturas do Mar Profundo\"? Mais vendida?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Não me diga que Doresain comprou um exemplar para cada pessoa na Necrópole..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Tulu sabe disso?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "É precisamente essa perspicácia aguçada sobre o coração humano e o Destino que faz com que eu realmente te admire."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "\"Todos Amam o Guardião\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Originalmente queria Disparar uma peça para você, mas considerando a portabilidade, escrevi como um romance."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Por favor, leve esta obra com você na sua Partida."
  },
  AvgCommunicate_137646_Content_3 = {
    Text = "Aquilo é..."
  },
  AvgCommunicate_137646_Content_4 = {
    Text = "\"O Grande Guardião\"? \"A Odisseia do Guardião\"? \"O Mundo do Guardião\"?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "O que você costuma escrever!? Alguém realmente lê essas coisas???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Não subestime sua popularidade em Misaq. Todas essas são obras extremamente populares."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Um Destino tão dramático naturalmente merece ser apresentado ao mundo."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "Na verdade, não é só você. Também teço histórias sobre os Destinos de outras pessoas."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "\"Cinco Anos no Campo de Batalha, Três Anos de Simulações\", \"Cuidados Pós-Parto para Ratos\", \"A Grande Exposição de Arte com Cera Derretida\"..."
  },
  AvgCommunicate_137646_Option_3 = {
    Text = "Aquilo é..."
  },
  AvgCommunicate_137647_Content_1 = {
    Text = "Conectando pessoas de diferentes tempos e espaços com fios invisíveis..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Aguardo ansiosamente, Guardião."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "A civilização humana nunca deixa de me surpreender."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "Surpreender?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "Mas esses destinos não foram escolhidos pela sua própria mão?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "O que escolho é Apenas a direção. Toda a civilização e a História ainda são criadas por vocês mesmos."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Os Fios do destino, estendendo-se naturalmente, darão Nascimento a novas criações de origens desconhecidas."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "É ao testemunhar tudo isso em silêncio, pela alegria desse têxtil, que sou capaz de carregar essa responsabilidade."
  },
  AvgCommunicate_137647_Content_8 = {Text = "Eu vejo..."},
  AvgCommunicate_137647_Content_9 = {
    Text = "Se houver novas criações, por favor, deixe-me apreciá-las também."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "Surpreender?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Algo parece estranho. O fato de que ninguém tem medo de mim..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Não se preocupe, todos têm sido tão gentis comigo! Estão seguros!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Provavelmente. Por enquanto."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Por enquanto? ...Por favor, torne isso definitivo!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Por enquanto～!"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll desenvolveu um feromônio especial. Agora, você parece nada mais do que uma garota humana comum para todos."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Conveniente, eu acho, mas..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "É quase um pouco decepcionante não poder mais assustar as pessoas?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Como eu coloco isso... hmm... por exemplo, vai tornar minha \"caça\" mais difícil..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Não tenho tido problemas para encontrar refeições ultimamente, então caçar não é uma necessidade urgente, mas... às vezes... é..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Já estou quase acostumado com todos os Corpos Despertos dizendo coisas desvairadas a essa altura, mas ainda preciso te dizer... Isso é uma coisa muito perigosa de se dizer!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Solicitação de Compra"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...E vou simplesmente fingir que não estou ciente de nada disso. Certo?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Quatro refrigeradores domésticos grandes... O orçamento da universidade não está exatamente apertado, mas para que você precisa dessas geladeiras?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Se não me engano, Saya, você já solicitou uma para colocar no seu dormitório no primeiro dia de mudança para cá."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Bem, hm... Nunca se sabe quando o espaço da geladeira vai ser útil..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Além disso, sabe, o frescor da carne é importante..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "..."},
  AvgCommunicate_140195_Content_7 = {
    Text = "Desculpe, mas não posso aprovar mais refrigeradores. No entanto, vou repassar os contatos de Xu e Doresain."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Acho que você se divertiria conversando com eles sobre comida e receitas."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "..."},
  AvgCommunicate_140196_Content_11 = {
    Text = "Errado! Você deveria dizer Splish Splash!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Aparentemente, o feromônio que a Professora Doll desenvolveu não funciona na Srta. Mosk."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Mas ela ainda me trata da mesma forma. A atitude dela não mudou nada."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Eu acho que é porque, hm, como eu coloco isso..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Talvez Mosk seja simplesmente dotado de... habilidades sociais extraordinárias?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abandonar. Ah, mais uma palavra aprendida. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Tenho estudado todos os tipos de idiomas ultimamente. ...É fascinante."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Além da Linguagem Leo padrão, também aprendi muito vocabulário novo. Por exemplo..."
  },
  AvgCommunicate_140196_Content_7 = {Text = "Glub glub?"},
  AvgCommunicate_140196_Content_8 = {Text = "Plop plop!"},
  AvgCommunicate_140196_Content_9 = {Text = "Correto!"},
  AvgCommunicate_140196_Option_10 = {Text = "..."},
  AvgCommunicate_140196_Option_8 = {Text = "Plop plop!"},
  AvgCommunicate_141374_Content_1 = {
    Text = "Um agradecimento tão formal pode parecer um pouco distante, mas, de coração, obrigado, por mim e por todo Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Eu demonstro essas características porque é assim que sou por natureza."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Não diga isso com um tom tão orgulhoso."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Portanto, me ajudar a tocar aquele limite e escapar do Seu controle foi realmente um grande favor."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Muitas coisas que antes eram difíceis de fazer já não são mais um problema."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Ainda dá tempo de eu recuperar o que dei?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Acalme-se, Pontos, Londinium tem um conjunto completo de leis!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Ser tão sério de repente... isso é realmente um pouco incomum."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Você provavelmente não sabe o que isso significa — antes de eu me tornar suficientemente poderoso, Ebwynnos nunca conseguia realmente escapar do controle daquela antiga presença."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Este foi o acordo que fiz com Ele. Felizmente, Ele não tinha más intenções, podendo até ser considerado generoso."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "No entanto, Ele definitivamente não pertence à humanidade. Sob o Seu controle, Ebwynnos se tornaria ainda mais imprevisível, e as pessoas de Ebwynnos teriam temperamentos ainda mais extremos."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Sendo assim, quer dizer que você antes também era assim por causa da influência Dele, tão, hm..."
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Deixa eu adivinhar, você quer dizer Paranoia, rancoroso ou maníaco por controle?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Não."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Um pouco incomum"
  },
  AvgCommunicate_141374_Option_6 = {
    Text = "Então quer dizer"
  },
  AvgCommunicate_143429_Content_1 = {
    Text = "Embora esses seguidores de culto que adoram falsos deuses sejam estúpidos a ponto de dar risada, é preciso admitir que alguns deles têm um gosto razoavelmente bom."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "E além disso, as épocas nem batem!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Eu acho que, se você se expusesse mais a esse tipo de influência e desenvolvesse mais ambição, talvez ajudasse a reduzir bastante o número de vezes que você pede socorro durante missões externas."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Claro, se você me chamar de tio mais vezes, fico feliz em continuar salvando crianças sem ambição."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "...Vou falar com Goliath agora mesmo."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Vou adicioná-los à lista de filmes proibidos de Misaq, sem ficar recomendando para qualquer um!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Já fiquei chocada alguns dias atrás, quando ele saía frequentemente de Misaq às escondidas de Miryam..."
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Você não estará se referindo a Goliath, não é..."
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Bem, primeiro, admiro muito a determinação dele em se submeter aos outros para alcançar seus objetivos."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Segundo, as peças que ele recomendou são realmente muito interessantes."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "É difícil imaginar que Goliath ainda frequente o teatro."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Ele me recomendou <Italic:Era Uma Vez em Leonia> e <Italic:O Pa▼drinho> — todos adoraram."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Esta noite, Ebwynnos deve exibir \"O Lobo de Londinium\"."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Não, espera, Misaq não permite a presença de chefes de gangue, e cultura de lobos também não!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Você não estaria se referindo a"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "O sexto pedido de transferência de residência deste mês, parece que os regulamentos da secretaria acadêmica nem sempre funcionam."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, que pena."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Hein?? Oi?! Por que um Yan pegou um gabarito de prova e sentou para começar a escrever minha dissertação?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Você carrega um fardo muito pesado, mesmo que tenha dito isso de brincadeira, isso mostra que você deveria Relaxar um pouco, meu pequeno."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Apenas desta vez, embora eu fique feliz em ajudar, ainda vou tentar não me tornar aquele tipo de pai que mima demais os filhos."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Agora, abra a janela, vou te levar para se divertir uma noite, para experimentar um pouco de diversão que faz esquecer a realidade sem precisar ir a Ebwynnos."
  },
  AvgCommunicate_143430_Content_15 = {Text = "...Eba!"},
  AvgCommunicate_143430_Content_3 = {
    Text = "Média de notas, frequência, taxa de conversão de prática efetiva, hm, e a pressão de emprego que existe para a maioria dos estudantes comuns, mesmo que o Guardião não a tenha."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Mesmo com a Dissolução bem à frente, os problemas da realidade ainda são assustadores."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "É normal que todos queiram escapar da realidade, que tal me levar também para Ebwynnos..."
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Você está falando sério?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Será que há realmente um som de asas batendo lá fora, ou estou tendo Ilusões depois de três noites seguidas de revisão."
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "A oportunidade não pode ser desperdiçada, com uma chance tão boa, mesmo que depois todo o Misaq venha me causar problemas, eu ficaria muito feliz em aceitar."
  },
  AvgCommunicate_143430_Content_9 = {
