  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Precisa de mim?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahahaha, tudo bem, não faça essa expressão."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Conseguir o selo pessoal dele não é difícil, quanto ao endereço do jantar de caridade, que tal realizá-lo em Ebwynnos?"
