  AvgCommunicate_143431_Content_15 = {
    Text = "Matá-lo quando ele estiver desprevenido talvez seja um pouco mais divertido."
  },
  AvgCommunicate_143431_Content_16 = {Text = "¿¿¿???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Hm, Pontos, você não quer considerar passar um tempo em Ebwynnos?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "O Professor Dexter já faz dois meses inteiros que não aparece Na Escola."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ha, essa coisa suja e covarde provavelmente está descontando sua raiva em algum subordinado azarado agora."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Pode ficar tranquilo, enquanto ele não fizer seu Retorno à sua Origem, ele ainda não tem qualificação para ser meu oponente."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "O problema é que tem uma pilha de documentos esperando o selo pessoal dele, e o banquete de caridade deste ano, o que fazemos! Fazer a Diretora Czort e a Professora Doll comparecerem a esse tipo de evento é mais difícil do que fazê-las explodir Misaq."
