  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Que tristeza, meu pequeno, eu sei, você tem a proteção de muitas pessoas em Misaq, não precisa mais de mim, e eu fiz tanto por você, você até mesmo..."
