  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Você me levou a um pico que anseei por muito tempo. Mas..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "O caminho da força não tem fim. Certo, Guardião?"
