  AvgCommunicate_145234_Content_7 = {
    Text = "Você está bem?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "O barulho de antes — era apenas fome. Uma coceira desesperada por não ser forte o suficiente, rápido o suficiente."
  },
  AvgCommunicate_145234_Content_9 = {
