  AvgCommunicate_146393_Content_7 = {
    Text = "É estranho se eu quiser todos..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Difícil escolha... que tal você escolher por mim..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "O chifre é bom. Levou três golpes antes de quebrar. Combina com você."
