  AvgCommunicate_146394_Content_1 = {
    Text = "Tenho um problema."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Fui embora três vezes. Cada vez que ia, eles começavam a se sacrificar. Aparentemente, achavam que era alguma provação divina."
  },
  AvgCommunicate_146394_Content_11 = {
