  AvgCommunicate_146394_Content_13 = {
    Text = "Não tirei minha lâmina do cadáver."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Agora eles a consagraram também."
  },
  AvgCommunicate_146394_Content_15 = {Text = "..."},
  AvgCommunicate_146394_Content_16 = {
    Text = "Preciso recuperar minha lâmina sem que eles cometam suicídio em massa na minha frente."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Você entende essas criaturas fracas melhor do que eu. Me ajude."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Ei, o que isso é suposto significar?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Uau, então até você tem problemas às vezes!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Ouvi dizer que havia um verme poderoso, então o matei."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Depois que ele morreu, as pessoas que ficaram presas por muito tempo dentro do planeta sob seu peso saíram engatinhando."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Elas me chamaram de deus, se curvaram para mim e até construíram uma estátua dourada minha — horrível demais."
  },
  AvgCommunicate_146394_Content_6 = {Text = "HAHAHAHAHA"},
  AvgCommunicate_146394_Content_7 = {
