  AvgCommunicate_146394_Option_9 = {
    Text = "Por que você não foi embora simplesmente?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Acho que você já sabe, hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hehe, não pense demais~ Pessoas que pensam demais se tornam adultos chatos e sem graça~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Embora, claro, se o Guardião do segredo simplesmente não conseguir resistir à atração pela Fada — se você se pegar seguindo cada um dos meus passos, dia e noite, só para conquistar meu verdadeiro afeto — bem, isso seria perfeitamente compreensível~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "Já deixei a maçã do amor mais gostosa de todas na mesa do seu dormitório."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Agora você deve, absolutamente deve, saboreá-la devagar, examinar cada mordida e aproveitá-la sozinho~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Então você passou por todo esse trabalho para conseguir uma autorização de saída... só para comprar maçãs do amor de edição limitada para Aigis, Ogier e Murphy, que disseram nunca ter experimentado?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Essas crianças pe— ahem — essas crianças devotas podem não ter pago suas contribuições de associação integralmente, mas desempenham um papel absolutamente vital na propagação das bênçãos da Fada."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Nutrir meu rebanho, para que espalhem a boa palavra com ainda mais entusiasmo — ora, esse é apenas mais um pesado fardo que a Fada carrega nos ombros~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Mesmo que você tivesse um bom motivo desta vez, por que é SEMPRE na minha conta que você vai cobrar..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, não se preocupe com detalhes~ Olha, as crianças agora são verdadeiras fiéis. Então quando você vai finalmente se juntar a elas, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Honestamente, não consigo dizer se você deixa escapar um fragmento do seu eu verdadeiro de vez em quando, ou se você é como uma cebola, sempre escondendo seu objetivo real sob mais uma camada..."
  },
