  AvgCommunicate_148439_Content_15 = {
    Text = "Maravilhoso~ Hee hee, Guardião do segredo — acredito que, uma vez que uma reclamação é retirada, você não pode registrar nenhuma nova contra o mesmo Corpo Desperto por um mês inteiro, pode?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Tenho um péssimo pressentimento sobre isso..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh, minha, a Fada jamais seria tão indelicada a ponto de brincar com o coração sincero de %player%~ Cada palavra naquela carta de desculpas era a pura verdade. Quando eu voltar do meu passeio, trarei a maçã vermelha mais doce para você~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Espera! Por que Aigis acabou de vir até mim em lágrimas, dizendo que, embora não faça ideia do que fez de errado, espera que eu a perdoe quando ver a carta de desculpas?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Carregando..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "E que você prometeu entregá-la — mas ela decidiu se desculpar pessoalmente também, só para garantir que eu não ficasse brava com ela de novo?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Ei, Caraboo. CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, você já usou esse truque uma vez. Não importa o que diga, NÃO vou abrir essa imagem."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Não, %player%... Eu realmente refleti sobre isso. Você, e todos em Misaq, foram tão gentis comigo. Eu realmente não deveria ter trazido meus velhos hábitos para este lugar tão bonito."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Afinal, eu nunca escolhi me tornar quem sou, não no começo."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Então me sentei e escrevi uma carta de desculpas de verdade — escrita à mão, cada palavra, pela minha própria mão~ Mas adivinha só, o Comunicador resolveu dar defeito exatamente neste momento..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Entendo se você não acreditar em mim. Vou apenas... esperar. O tempo que for necessário para você voltar a confiar em mim..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, por que minha consciência está me incomodando? De qualquer forma, de jeito nenhum eu vou..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Imagem]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "Do que você está falando? Como se eu fosse te pagar de volta!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Huh?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Você nem está fingindo mais?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hehee. Servir à Fada é, por si só, sua maior honra. Ela te guiará a um paraíso incomparável. Perto disso, recompensas mundanas mal merecem ser mencionadas, é claro."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Chega disso! Se você não transferir o dinheiro logo, o mapa será perdido para sempre..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Já olhei para essa coisa que você me enviou. Era claramente uma falsificação feita com alguma tecnologia de Núcleo de prata ordinária..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh? Você abriu? Isso foi inteiramente sua própria escolha, saiba~ Maravilhoso! *A Fada lembrará da oferta de %player% para sempre.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Espera, por que estou recebendo uma notificação de que 1.000 Florins foram deduzidos — essa é a minha bolsa de trabalho de campo!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Carregando..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Calma, calma. Você é bem abastado, não é? Desta vez vou levar apenas 200 Florins — como pagamento pela gentil lição de que não se deve abrir links desconhecidos no seu comunicador. Seja grato pela misericórdia da Fada, está bem?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Transferência: 800 Leonian Florins]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Imagem Corrompida]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...O que você enviou?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Oops!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "Estamos perdidos! Essa imagem continha um mapa para o Leste, conquistado com o sangue, suor e lágrimas dos meus devotos seguidores — e agora o original foi corrompido junto com ela! Deve ser algum @2 maligno tentando nos impedir de chegar ao Leste!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, quantos Florins você tem? Rápido, me dê todos eles! Ainda há uma chance de recuperá-lo..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Deixa eu adivinhar, você vai me pagar dez vezes mais quando chegar ao Leste. Não nasci ontem, saiba."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Um golpe que não acompanha os tempos não tem futuro."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "A missão de escolta que a academia me confiou anteriormente já foi concluída. Por favor, há algo que o Senhor precise que eu faça?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "De qualquer forma, se você não quer ficar parada, daqui a alguns dias haverá muitas atividades na escola, que tal ir se divertir um pouco?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Se é uma ordem do Senhor, obedecerei."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Vou fazer a ronda agora."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Espero que você realmente obedeça depois!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Você não vai descansar um pouco?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "Não há necessidade."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Além disso... não tenho o direito de desfrutar de tal tranquilidade."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Aquela sombra ainda me perturba de vez em quando, sussurrando em meu ouvido."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Talvez quando estou ocupada com algo, eu me sinta mais tranquila."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "É só isso, o Senhor não precisa se preocupar."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Talvez eu precise ensinar a necessidade de dar uma folga de vez em quando."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Relaxar mais para poder lutar melhor."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Talvez eu precise ensinar a necessidade de dar uma folga de vez em quando."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Relaxar mais para poder lutar melhor."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph... você está me zombando? Este já é o limite do controle que consigo exercer sobre este corpo agora!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "O que você pretende fazer? Continuar instigando e manipulando ele?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Se eu pudesse fazer isso, já teria..."
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Deixa para lá. Em vez de me tornar uma lâmina, ser um escudo ou uma barreira também não parece tão ruim..."
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Quanto ao senhor em quem ele confia e serve — você — ao interagir, acabou sendo bastante interessante."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Entendi, você foi influenciado de volta por Ogier, não foi."
  },
  AvgCommunicate_149950_Content_16 = {Text = "..."},
  AvgCommunicate_149950_Content_17 = {Text = "¿¿¿???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Senhor, peço desculpas. Acabei apagando por alguns minutos agora há pouco."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Quando voltei a mim, vi o comunicador aceso."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Finalmente te encontrei..."
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Tenho a sensação de que, há pouco, ouvi aquela voz irritante depois de tanto tempo..."
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Como direi... parece que você e a força que habita em você já conseguem coexistir em bastante harmonia."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...Terminei de ler o registro."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Eu ainda temia que Ele fosse, como antes, proferir palavras malignas e agressivas."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Que surpresa, antes era eu quem sempre sofria a erosão Dele, mas agora parece que se inverteu."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Isso deve ser algo bom. Pelo menos... isso significa que já O venci completamente."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Claro, será que foi por causa do aumento do poder de Ogier que o controle sobre essa entidade invisível pôde chegar a esse nível?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Sim, deve ser isso. Com certeza são mudanças que surgiram por sua causa."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "Além disso, para mim, a \"Lei Final\" que compreendi não é apenas poder..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Há também essa crença de proteger os outros, que arde em meu peito com mais fervor do que de costume. Acredito que essa seja a verdadeira origem."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Você não é Ogier, quem é você?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Devolva o comunicador ao seu dono!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Ridículo. Se não fosse pela minha existência, como essa criança teria sobrevivido, e como poderia permanecer aqui como um Corpo Desperto?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Você é... aquela presença invisível que está ligada a ele?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Exatamente. Guardião do Segredo de Misaq, como você pode não me reconhecer."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Bem... é que você sempre foi fortemente suprimido por Ogier, então eu simplesmente nunca cheguei a te ver."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Você não é Ogier, quem é você?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Devolva o comunicador ao seu dono!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Meu senhor, vim até o senhor para fazer um convite."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...Uma árvore."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Huh?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Talvez seja porque recebi treinamento profissional — não importa o quanto o caos se instale, consigo permanecer firme no palco."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "O que diabos vai acontecer nessa peça de vocês!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Não sei, sou apenas uma árvore."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Bom, durante a apresentação, Jenkin, que interpreta a princesa, vai descer dos céus, e Lily, que interpreta o príncipe, vai pegá-la."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis, que interpreta o rei demônio, ainda vai descer ao palco para interagir com o público."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Já nem tenho mais vontade de comentar sobre essa distribuição de papéis..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Mas, isso não seria um spoiler da sua parte?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Porque não quero esconder nada do senhor."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "O clube de teatro irá encenar uma peça de conto de fadas, reunindo os Corpos Despertos menores de idade de Misaq para atuar juntos."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Além disso, com base nos ensaios, algo diferente e inesperado acontece a cada vez, então não posso garantir o que o senhor verá de fato."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...Isso realmente desperta muita curiosidade."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Esses comportamentos durante a apresentação carregam certo grau de perigo."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Por isso, enquanto interpreto a árvore, preciso ficar atento ao máximo à situação no palco e na plateia, garantindo a segurança dos atores e do público."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Então você foi lá fazer um bico como segurança... Parece bem cansativo."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Sim. De qualquer forma, fique tranquilo. Enquanto eu ainda estiver no palco, não deixarei ninguém se machucar novamente."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "É um pouco difícil de dizer... eu também subirei ao palco. Espero que o senhor venha assistir."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Estou muito animado."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Mas, não esperava que você concordasse em participar de um evento assim."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Bem, já faz tempo que não sou mais uma criança, por isso não seria adequado participar."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Porém, elas insistiram muito..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Não quero estragar a diversão delas e, além disso, percebi que esse papel realmente só pode ser interpretado por mim."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Então, que papel Ogier vai interpretar? Um cavaleiro?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Senhor, por favor, há alguma aula relacionada ao Fenômeno de Erosão recentemente?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Que dedicação... Se eu fosse tão esforçado quanto você, com certeza não precisaria me preocupar com provas."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Por favor, não me elogie assim. As responsabilidades que você carrega são muito mais pesadas do que as minhas."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Além disso, isso é apenas o dever necessário que cumpro para expiar meus pecados."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Mas você aprende muito rápido. Quem sabe Ogier também tem potencial para se tornar um estudioso."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Como todo mundo pensa quando criança, sobre o futuro."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Ogier já pensou no que quer fazer quando crescer?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Você sabe que já me tornei um Corpo Desperto, não há mais possibilidade de crescer e me tornar adulto."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Mesmo assim, pode sonhar um pouco com os planos para o futuro! Não precisa ser tão pessimista."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Ogier não tem nada que queira fazer além de \"proteger os outros\"?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Obrigado pelo encorajamento."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Quero aprender mais a fundo sobre isso."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Quanto a outras coisas que quero fazer... desculpe, realmente não consigo pensar em nada."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Quando este corpo não estiver mais manchado pelo pecado, aí sim vou pensar nisso."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Claro, claro, depois te levo junto comigo."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Mas por que Ogier de repente quer aprender sobre esse assunto?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Porque hoje alguém me perguntou se o poder que me envolve tem relação com a Lama Corrosiva."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Já vejo, olhando só para a forma, de fato há uma certa semelhança."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Sim, sempre me preocupei com a essência dessa coisa invisível. Talvez, ao compreendê-la suficientemente, eu consiga controlá-la melhor."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Embora, depois de chegar a Misaq, tenha percebido que existências difíceis de compreender são muito mais numerosas do que eu imaginava......"
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Por isso decidi primeiro aprender mais sobre o conhecimento relacionado à corrosão, afinal esse também é o inimigo que meu senhor enfrenta há muito tempo."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, meu filhotinho desobediente, sempre vagando pelo mundo inteiro."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Ninguém se importa com o seu William."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Apenas não se esqueça: você é meu filhotinho de estimação pessoal. Qualquer ameaça à sua vida miserável é simplesmente uma perda dos meus bens."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Além disso, eu escolhi a dedo este mundo específico — uma pequena fissura, a salvo da Dissolução."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Então tome cuidado. Tente não quebrá-lo."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Seu sinal está falhando de novo. Em que terra desolada você foi se meter dessa vez?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Estou no Continente do Norte Final."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Estou bem lá no alto das terras elevadas."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Estamos nos preparando para escalar uma montanha a seguir. Honestamente, estou um pouco preocupado com meu fôlego."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "O ar aqui é incrivelmente rarefeito. Parece que vou desmaiar se correr mais do que alguns passos."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "E você realmente acha que consegue escalar uma montanha assim? Que filhotinho imprudente e sem juízo, completamente alheio aos seus próprios limites."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Eu sei que você está apenas preocupado, mas tenho coisas que preciso terminar."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Não se preocupe, o Sênior William está aqui comigo. Vai ficar tudo bem."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Continente do Norte Final."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Uma região de alta altitude."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Um leve tremor ondula pelos confins da tapeçaria do destino."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Isso é mais um fio na sua tapeçaria do destino?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Sobre isso, o tear deve permanecer em silêncio."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "E as pessoas que vivem neste mundo? O que acontece com elas agora?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Elas retornarão à sua essência mais pura — os Núcleos de prata."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "E o Rei-Deus recolherá esses fragmentos da chuva interminável, remodelando o mundo após um longo e silencioso sono."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Esta testemunha silenciosa será compartilhada."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "O limiar crítico foi cruzado. A terra prometida tão longamente buscada é finalmente alcançada."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Não consigo acreditar nisso."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "O mundo está desaparecendo."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "O céu está derretendo, a neve está desmoronando, os picos das montanhas estão se desfazendo."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Este mundo inteiro... era tudo falso."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Você sempre soube? Sempre foi capaz de ver isso?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Estar fora do grande palco do mundo é tecer para a eternidade."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Isso incluía o desejo de Caraboo? O mundo não teria desaparecido sem ele."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Eu consigo ver..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "O mundo está desaparecendo..."
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Parceiro, você terminou de ler os livros sobre história e ciências naturais que eu te emprestei da última vez?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Huh? Precisa realmente ser tão sério...?"
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Estes são livros essenciais para investigadores. Você deve memorizar alguns, mesmo que tenha que fazê-lo de cor."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Eu planejo te dar tutoria por uma hora todos os dias. Se você quiser aprender mais rápido, não me importo em ficar acordado a noite inteira com você."
  },
  AvgCommunicate_57593_Content_13 = {
