  AvgCommunicate_66979_Content_11 = {Text = "Obrigado."},
  AvgCommunicate_66979_Content_2 = {
    Text = "Sim! Sabíamos que você não comeria nada, mas todos queriam que você participasse da diversão, então enviamos para aí."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Obrigado pelo gesto gentil. Por favor, transmita minhas Bênçãos de aniversário em meu nome, e... seria possível enviar outra fatia de bolo?"
