  AvgCommunicate_66981_Content_1 = {
    Text = "Guardião, quais são seus pensamentos sobre as emoções humanas?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "E quanto a você? Como um Corpo Intelectual, você não deveria ser absolutamente racional?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Você é perspicaz, Guardião, o que é uma razão pela qual sempre tentei minimizar meu contato com o mundo."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Quando me distancio do mundo e evito manter laços excessivamente próximos com humanos, permaneço com a mente clara e independente."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "É como se eu nunca tivesse provado a doçura do bolo, eu não pensaria constantemente nele na minha mente."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Eu vejo... Então, você quer comer alguns bolinhos agora?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "Não é uma necessidade, mas se for conveniente para você, ficaria muito grato."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "Tal tópico profundo logo de início!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Emoções... todo mundo as tem, afinal, somos apenas humanos."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Exatamente, os humanos existem dependendo de sua carne, e as emoções surgem de reações instintivas."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "A maioria das escolhas humanas é influenciada por emoções em vez de pensamento racional, que exige contenção e esforço."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "De fato, manter a racionalidade absoluta o tempo todo parece ser possível apenas para a Professora Boneca."
