  AvgCommunicate_66983_Content_13 = {
    Text = "A produção começou ontem, e já está nas prateleiras da cafeteria. Há muitas pessoas na fila!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Então você foi quem fez aqueles novos mini bolos que todo mundo correu para comprar ontem!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahahaha, sou incrível ou não? Me chame de gênio!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Genius!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Mas eu de repente percebi que bolos caseiros podem ter um gosto melhor. Manter isso a partir de agora não é uma má ideia."
