  AvgCommunicate_66984_Option_9 = {
    Text = "Então o assunto não está resolvido?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Meu pequeno Cavaleiro, graças à sua ajuda na Dança da última vez, consegui me livrar daquela pessoa terrível."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Um desejo? Então eu desejo que a bela Senhora Sorel compartilhe um suntuoso jantar à luz de velas comigo."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Apenas eu e a senhora, sem precisar entreter mais ninguém."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Como desejar, sua criaturinha astuta."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "O que você gostaria de comer? Diga-me, e eu saborearei junto com você."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Isso realmente testa a imaginação de alguém como eu que come no refeitório todos os dias. Bem então, me deixe provar — o que a senhora mais adora comer."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Hehe, que criança encantadora você é."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Então, aguardarei sua visita em minha residência."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Para agradecer sua bondade e generosidade, gostaria de fazer algo por você como sinal da minha gratidão."
  },
