    Text = "A senhora é bondosa demais, Senhora Sorel. Eu pensava que nossa relação já tinha passado do ponto de precisar dizer obrigado."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "De fato, não gosto de expressar gratidão em palavras. Na maioria das vezes, são Apenas gentilezas vazias."
