  AvgCommunicate_66985_Option_3 = {
    Text = "A senhora é bondosa demais, Senhora Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Uau, algum pedido?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Agora a senhora me deixou sem saber o que dizer..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Lotan e eu acabamos de ter um combate. Foi um empate."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ahaha... Acho que não tenho tantos pensamentos distrativos assim, então vou passar por agora..."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Então você também é forte."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Infelizmente, sempre tem alguém pescando ao lado daquela cachoeira. É um pouco barulhento."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Uma vez saí da cachoeira e tentei pedir para ele fazer menos barulho. Ele ficou tão assustado que jogou o peixe na minha cara e saiu correndo."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Será que ele vai voltar da próxima vez?"
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm... Acho que não vai..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "O que aconteceu entre vocês dois?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Vocês não brigaram, brigaram?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Não, Apenas um duelo de treino entre guerreiros."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Antes, ela disse que minha luta não era pura o suficiente. Acho que agora eu entendo."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Encontrei um jeito de me tornar mais puro. O eu atual é mais forte."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Isso é bom, mas que método você usa para se tornar mais puro?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Fique Abaixo de uma cachoeira e deixe a água lavar seus pensamentos distrativos."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "É muito eficaz. Quer ir junto?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ahaha... Acho que não tenho tantos pensamentos distrativos assim, então vou passar por agora..."
  },
  AvgCommunicate_66986_Option_15 = {
