    Text = "O que aconteceu entre vocês dois?"
  },
  AvgCommunicate_66986_Option_3 = {
    Text = "Vocês não brigaram, brigaram?"
  },
  AvgCommunicate_66986_Option_7 = {
    Text = "Isso é bom, mas que método você usa para se tornar mais puro?"
  },
  AvgCommunicate_66987_Content_1 = {
    Text = "Guardião, você conhece alguma receita de peixe?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Que senhora bondosa e gentil."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm. Então, eu quero aprender a cozinhar peixe também. Da próxima vez, serei eu a cozinhar para ela."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "Que emocionante! Você precisa fazer isso! Vou interrogar o cozinheiro do refeitório para você agora mesmo!"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Obrigado."},
  AvgCommunicate_66987_Content_2 = {
    Text = "Receitas?? Você vai cozinhar?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, depois que eu espantei o pescador da última vez, ficou tranquilo perto da cachoeira por um bom tempo."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Recentemente, uma senhora idosa tem vindo aqui pescar. Ela nunca faz barulho, então eu nunca me mostrei."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Depois, uma vez, ela acendeu uma fogueira e estava grelhando o peixe que pescou."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "O cheiro era tão bom que meu estômago fez um barulhinho, e ela me descobriu."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Hã? Você a assustou também?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "Não, ela me convidou para comer o peixe grelhado junto. Estava delicioso."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "Depois ela começou a trazer uma panelinha quando vinha pescar, e então fazia sopa de peixe e dividia comigo."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Que senhora bondosa e gentil."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "Que emocionante! Você precisa fazer isso! Vou interrogar o cozinheiro do refeitório para você agora mesmo!"
