  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Hã? Você a assustou também?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Recentemente recebi uma boa quantia em dinheiro, mas quase morri no processo. Felizmente, a deusa da sorte sempre me concede sua Bênção."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Mas quando começamos a lutar, a armadilha que ele montou disparou acidentalmente e acertou nele."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Eu até fiz um controle de Sangue de emergência nele, e foi só por isso que ele ainda estava vivo quando o levei à delegacia."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "A polícia me deu uma recompensa. O condenado voltou para a prisão, e ouvi dizer que a sentença dele vai ser mudada para perpétua."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Faltavam apenas mais alguns anos para ele poder sair. Por que ele teve que fazer algo tão tolo... *suspiro*..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Dificuldade em dizer quem está pior, você ou ele..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Mas espera, não vieram pessoas da Aposta Lavka atrás de você ontem mesmo para cobrar uma dívida? O que aconteceu com o dinheiro da recompensa?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ahaha... Bem, minha sorte é limitada, afinal. Se eu gasto tudo antecipadamente, é inevitável que eu perca algumas mãos na mesa..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Ouvindo isso, de repente me sinto bem melhor sobre as coisas."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "O que aconteceu??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Sabe, eu costumo aceitar comissões de detetive por aí. Minha taxa de sucesso na resolução de casos é tão alta que sempre fui muito requisitada."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Mas, por outro lado, aqueles criminosos que mandei para a prisão me odeiam profundamente."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Bem, eles perderam das formas mais desconcertantes, afinal."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Alguns dias atrás, um condenado fugiu da prisão e ficou de tocaia na Aposta Lavka que eu frequento por dias, até que finalmente me pegou."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Ele estava lá para se vingar de você?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Isso mesmo. Ele me seguiu por um longo tempo e finalmente me encurralou em um beco."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Ele tinha preparado armadilhas no beco de antemão, com a intenção de me matar."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Dificuldade em dizer quem está pior, você ou ele..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "Ouvindo isso, de repente me sinto bem melhor sobre as coisas."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "O que aconteceu??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Bem, eles perderam das formas mais desconcertantes, afinal."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Ele estava lá para se vingar de você?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Guardião, terminei de compilar os protocolos de gestão de crises do Investigador sobre os quais você me consultou."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Embora eu possa ser mais atenta às suas necessidades do que aquela Ramona, não se esqueça— eu também já fui ela."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Se quiser me enganar, vai precisar de mais prática."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Ai... Minha sinceridade foi desperdiçada com a pessoa errada!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Então sobre aquele dever de casa— quer dizer, aquela questão— pelo menos me dê uma dica de como abordá-la!"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "Maravilha! Eu sabia que você era a mais confiável."
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Obrigada, mas você poderia facilmente perguntar à Ramona do seu próprio mundo sobre esse tipo de questão. Por que veio até mim?"
  },
  AvgCommunicate_66989_Content_4 = {
    Text = "Você sabe como é— aquela Ramona sempre foi tão séria com tudo. Se eu for perguntar diretamente a ela, com certeza vai me fazer pensar por conta própria."
  },
  AvgCommunicate_66989_Content_5 = {
    Text = "Mas a questão é esta! Eu acredito que o aprendizado progride mais rápido através de discussão mútua e troca de ideias!"
  },
  AvgCommunicate_66989_Content_6 = {Text = "Entendido."},
  AvgCommunicate_66989_Content_7 = {
    Text = "Então você está me pedindo para ajudar a terminar o seu dever de casa."
  },
  AvgCommunicate_66989_Content_8 = {Text = "?!"},
  AvgCommunicate_66989_Content_9 = {
    Text = "D–definitivamente não é isso, como poderia ser, ahaha..."
  },
  AvgCommunicate_66989_Option_12 = {
    Text = "Ai... Minha sinceridade foi desperdiçada com a pessoa errada!"
  },
  AvgCommunicate_66989_Option_2 = {
    Text = "Maravilha! Eu sabia que você era a mais confiável."
  },
  AvgCommunicate_66989_Option_4 = {
    Text = "Você sabe como é..."
  },
  AvgCommunicate_66989_Option_8 = {Text = "?!"},
  AvgCommunicate_66990_Content_1 = {
    Text = "Guardião, os nomes de todos são tão difíceis de escrever. Eu não consigo lembrar quais personagens eles são!"
  },
  AvgCommunicate_66990_Content_10 = {
    Text = "Então, então eu mudarei isso! Você não deve contar!"
  },
  AvgCommunicate_66990_Content_11 = {
    Text = "Tudo bem, tudo bem, quais são os nomes de Aigis e Lily?"
  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Claro, os nomes deles são Aigis e Lily. Eles são amigos. Amigos não podem ter o mesmo nome!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "Então por que eu sou chamado de Guardião..."
  },
  AvgCommunicate_66990_Content_14 = {
    Text = "Não é praticamente a mesma coisa? Não seja mesquinho! Ajude-me a criar codinomes para os outros!"
  },
  AvgCommunicate_66990_Content_15 = {
    Text = "Eu acho que é mais confiável primeiro encontrar alguém que te ensine a ler e escrever."
  },
  AvgCommunicate_66990_Content_2 = {
    Text = "Bem, é de fato um pouco desafiador para você. Que tal deixar Ramona lhe dar uma aula de alfabetização?"
  },
  AvgCommunicate_66990_Content_3 = {
    Text = "De jeito nenhum! E se eu sou do Lado Oeste? Você não pode aceitar alguém que não sabe ler?"
  },
  AvgCommunicate_66990_Content_4 = {
    Text = "Não... Você não trouxe isso primeiro!"
  },
  AvgCommunicate_66990_Content_5 = {
    Text = "Hmph, um problema tão trivial não pode enganar um mestre ladrão como eu."
  },
  AvgCommunicate_66990_Content_6 = {
    Text = "Decidi dar a todos um nome código para que eu possa anotá-los."
  },
  AvgCommunicate_66990_Content_7 = {
    Text = "Por exemplo?"
  },
  AvgCommunicate_66990_Content_8 = {
