  AvgCommunicate_66991_Content_13 = {
    Text = "Marrom?! O Marrom está na sua casa?"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Sim, pode parar de procurar. Além disso, ele se enroscou na minha camisa e está com uma das minhas meias na boca e não quer largar. Tem ideia do que isso significa?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "I-isso é definitivamente só um hobby de rato. Não tem nada a ver comigo!"
