  AvgCommunicate_66991_Content_16 = {
    Text = "Na pior das hipóteses, eu compro um par de meias novo pra você."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Marrom? Ele não está sempre com você?"
  },
  AvgCommunicate_66991_Content_3 = {
