  AvgCommunicate_67012_Content_3 = {
    Text = "Mm... Se você passar pelo centro da cidade, tiver algum tempo e for conveniente, poderia me trazer um novo novelo de lã?"
  },
  AvgCommunicate_67012_Content_4 = {
    Text = "Quero consertar a boneca, e o vestido, e as roupas de todos. A capa do Jenkin também está ficando um pouco gasta..."
  },
  AvgCommunicate_67012_Content_5 = {
    Text = "Os fios não são suficientes? Vou lembrar. Que cor você quer?"
  },
  AvgCommunicate_67012_Content_6 = {
    Text = "Que tal eu levar você para comprar roupas novas? Vamos convidar Jenkin e Lily."
  },
  AvgCommunicate_67012_Content_7 = {
    Text = "Não, não precisa! Minhas roupas ainda são usáveis. Seria um desperdício..."
  },
  AvgCommunicate_67012_Content_8 = {
    Text = "Como isso pode ser um desperdício, Aigis? Não há necessidade de ser tão cauteloso. Todos nós estamos felizes em cumprir seus desejos."
  },
  AvgCommunicate_67012_Content_9 = {
    Text = "O financiamento diário de Mythag é mais do que suficiente. Ninguém irá abandoná-lo novamente, entendeu?"
  },
  AvgCommunicate_67012_Option_11 = {Text = "Bom."},
  AvgCommunicate_67012_Option_2 = {
    Text = "Qual é o problema?"
  },
  AvgCommunicate_67012_Option_5 = {
    Text = "Os fios não são suficientes? Vou lembrar. Que cor você quer?"
  },
  AvgCommunicate_67012_Option_8 = {
    Text = "Como isso poderia ser um desperdício?"
  },
  AvgCommunicate_67013_Content_1 = {
    Text = "Guardião, Salve-me! Sinto como se formigas estivessem a rastejar por todo o meu corpo!"
  },
  AvgCommunicate_67013_Content_10 = {
    Text = "Esvazie os sacos de pancada da sala de treinamento e se enfie dentro de um. Lembre-se: não faça nenhum som."
  },
  AvgCommunicate_67013_Content_11 = {
    Text = "Meu Deus, Guardião, você é o melhor!"
  },
  AvgCommunicate_67013_Content_2 = {
    Text = "...O que se passa contigo? Se estás doente, podes ir à enfermaria."
  },
  AvgCommunicate_67013_Content_3 = {
    Text = "Eu, eu não sei, sinto que mal consigo respirar..."
  },
  AvgCommunicate_67013_Content_4 = {
    Text = "Assim tão grave? Onde estás? Devo chamar um Médico tratante imediatamente?"
  },
  AvgCommunicate_67013_Content_5 = {
    Text = "Estou na... Estou na sua Porta, por favor, me bata! Não apanho há três dias! Estou me sentindo péssimo!"
  },
  AvgCommunicate_67013_Content_6 = {Text = "..."},
  AvgCommunicate_67013_Content_7 = {Text = "..."},
  AvgCommunicate_67013_Content_8 = {
    Text = "Já entrei em contato com os Vigilantes e arranjei um novo trabalho para você. Eles vão te levar até lá."
  },
  AvgCommunicate_67013_Content_9 = {
    Text = "Que trabalho?"
  },
  AvgCommunicate_67013_Option_10 = {
    Text = "Esvazie os sacos de pancada da sala de treinamento e se enfie dentro de um. Lembre-se: não faça nenhum som."
  },
  AvgCommunicate_67013_Option_2 = {
    Text = "...O que se passa contigo? Se estás doente, podes ir à enfermaria."
  },
  AvgCommunicate_67013_Option_4 = {
    Text = "Assim tão grave? Onde estás? Devo chamar um Médico tratante imediatamente?"
  },
  AvgCommunicate_67013_Option_6 = {Text = "..."},
  AvgCommunicate_67013_Option_7 = {Text = "..."},
  AvgCommunicate_67014_Content_1 = {
    Text = "Guardião, às vezes me pergunto se tudo que fiz realmente satisfaz meu rei?"
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "Mas acredito que a única coisa que os deuses podem sentir é a dedicação devota e apaixonada de seus seguidores."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "Então talvez o que você fez não seja a parte mais importante; o que importa é o coração que você colocou nisso. Afinal, Tulu nunca te impediu, certo?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "Eu nunca esperei ser iluminado por um cético como você. Suas palavras deixaram uma profunda impressão em mim. Obrigado."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "O caminho que escolhi é realmente o certo?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "Nunca esperei que você refletisse sobre si mesmo um dia."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Porque eu também me sinto confuso, cansado e desanimado. Se tudo que faço está certo, por que o Rei não respondeu a mim?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Embora eu não seja tão devoto quanto você, acredito que o que os seguidores fazem por Deus não é necessariamente o que Deus precisa."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "O que você disse?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Ei, ei, não se apresse. Eu ainda não terminei de falar."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "A diferença entre mortais e deuses é semelhante à que existe entre formigas e humanos. Eu não acredito que os humanos possam compreender totalmente as necessidades dos deuses."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Formigas... Talvez você esteja certo."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "Mas eu acredito..."
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "Nunca esperei que você refletisse sobre si mesmo um dia."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Embora minha fé não seja tão devota quanto a sua..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Ei, ei, não se apresse. Eu ainda não terminei de falar."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Guardião, as palestras que dei no campus e os panfletos promocionais que imprimi foram muito bem recebidos."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "Senhorita Sanga? Eu raramente a vejo. Ouvi dizer que Ela é uma escultora excepcional."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "Se ela estiver disposta a esculpir para meu Senhor, seria perfeito; o Reino Divino a protegerá."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "Eles desenvolveram sentimentos de reverência pelo meu grande Lorde. Alguns dos fiéis me disseram que desejam obter estatuetas em miniatura do Lorde, para que possam Liberar sua Oração e adorar convenientemente em seu quarto."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "Acho que eles têm razão. Onde eu poderia encontrar um artesão para fazer um lote Personalizado dessas estatuetas?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "Estatuetas em miniatura? Tem algo estranho nisso..."
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "O que há de errado? Essas estatuetas realmente exigem um trabalho artesanal refinado. Não existem tais artesãos na Misaq?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "Não é bem sobre os artesãos... é Apenas que tenho a sensação de que eles não querem essas estatuetas para Oração e adoração..."
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Impossível. Eu testemunhei pessoalmente o Fervor deles pelo meu Lorde. Eles até se importam com cada detalhe das preferências e da vida cotidiana do Lorde."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Isso Apenas prova meu ponto... Deixa pra lá, o que te fizer feliz."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "Vou perguntar à Sanga se ela está disposta a fazer esse lote de estatuetas."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "Estatuetas em miniatura? Tem algo estranho nisso..."
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "Não é bem sobre os artesãos..."
  },
  AvgCommunicate_67015_Option_8 = {
    Text = "Isso Apenas prova meu ponto... Deixa pra lá, o que te fizer feliz."
  },
  AvgCommunicate_67016_Content_1 = {
    Text = "Suspiro, Guardião, vim confessar minha negligência a você e ao Lorde Dexter, e espero receber seu perdão."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Ahem, é bastante lamentável, mas não é culpa sua. Não se culpe."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "Não, isso tudo foi por descuido meu. Farei uma autocrítica pública e reforçarei a gestão do dia a dia."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "Devido à minha má gestão pessoal, dois pacientes do Sanatório foram gravemente envenenados. Felizmente, agora estão fora de perigo após tratamento de emergência."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "Huh? O que aconteceu?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Bem, atrás do Sanatório há um pequeno lago que poucas pessoas costumam visitar."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Você sabe do meu apreço pela água. Em dias de trabalho intenso, eu escapava silenciosamente para o lago à noite e aproveitava um momento de Tranquilidade serena no mundo subaquático."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... Isso é compreensível. O trabalho é sempre estressante, afinal."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Talvez porque eu tenha ido vezes demais, as toxinas do meu corpo foram se espalhando gradualmente pelo lago e pelos peixes que viviam lá."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "Originalmente, esse lago não ficava na área de atividades dos pacientes, mas dois dias atrás, dois pacientes gulosos escaparam até o lago para pescar e assar os peixes para comer."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Quando o pessoal médico os descobriu, eles já estavam espumando pela boca e tinham desmaiado no chão..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Ahem, é bastante lamentável, mas não é culpa sua. Não se culpe."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Huh? O que aconteceu?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... Isso é compreensível. O trabalho é sempre estressante, afinal."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Guardião, um visitante de Misaq por acaso ouviu meu canto durante o ensaio."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Você ama cantar, ama se apresentar — por que não deixar sua voz ser ouvida por mais pessoas?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Amor... Agora eu entendo. Obrigada, Guardião."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Vou tentar brilhar mais uma vez neste planeta."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Agora estão me convidando para colaborar com a empresa deles para lançar alguns discos. Devo aceitar?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "Acho que deveria! Se bem me lembro, você costumava ser uma cantora famosa, certo?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Sim, minhas canções foram uma sensação no Wild Star, mas na maioria das vezes, foi apenas para negociar com a nobreza."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Agora que tenho minha irmã de volta, não preciso de mais nada."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "E quanto a você? Você ainda se sente feliz quando canta?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Feliz... Suponho que sim, sou feliz. Afinal, cantar é a Apenas coisa que sei fazer."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "Não, Tinct, ninguém continuaria praticando canto todos os dias se não amasse de verdade."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Agarrar-se ao que se ama é Apenas natural."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "Acho que deveria! Se bem me lembro, você costumava ser uma cantora famosa, certo?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "E quanto a você? Você ainda se sente feliz quando canta?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Ninguém continuaria praticando canto todos os dias se não amasse de verdade."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "Mensageiro Pálido, quis entrar em contato especificamente para informar que visitarei Misaq em breve."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "Minha visita anterior parece ter sido de alguma ajuda para todos, e fui convidada a voltar para conversar com todos no auditório."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Se por acaso tiver algum tempo livre, espero que possamos nos encontrar no campus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "Eu adoraria!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Maravilhoso. Reservarei um tempo só para você, para ouvir tudo o que quiser me contar."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Apenas nós dois?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Sim. Afinal, isto não é um culto—Apenas um encontro entre amigos, não é?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Sem problema. Farei um tour pelos pontos turísticos de Misaq. Talvez queira experimentar a cafeteria dos Corpos Despertos?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Seguirei seus planos. Estou ansiosa por isso."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "Eu adoraria!"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "Apenas nós dois?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "Sem problema!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Mensageiro Pálido, o distrito do Santuário realizará uma grande Missa em breve."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Seu coração sincero me enche de tanto calor. Então não recusarei mais."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Por favor, venha quando tiver tempo livre, e me ajude com uma limpeza e decoração simples."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Sem problemas, até logo!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Obrigado mais uma vez, Mensageiro Pálido. Que o Pai Deus vigie O Caminho da Mecha diante de você."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Eu presidirei a cerimônia, compartilhando os ensinamentos do Pai Deus."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Crentes de Londinium e das áreas ao redor todos estarão presentes. Se tiver interesse, é bem-vindo para se juntar a esta celebração eucarística também."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "Adoraria! Mas com tantos crentes para atender, os preparativos para esta Missa devem ser um grande desafio."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Você é sempre tão atencioso, gentil e considerado com os outros."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "De fato, garantir que todos estejam devidamente acomodados e possam sentir a graça do Pai Deus requer uma grande quantidade de preparativos."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Mas não se preocupe. Ainda há vasta Experiência em presidir Missas e posso lidar bem com essas questões triviais."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Nenhuma quantidade de Experiência lhe dá mãos extras. Se possível, deixe-me ir mais cedo e ajudá-lo!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Afinal, para um evento tão grandioso, quanto mais minuciosos os preparativos, melhor."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Sem problemas, até logo!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "Eu adoraria!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Se possível, deixe-me ir mais cedo e ajudá-lo!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Suspiro, desde que a Misaq emitiu aquela ordem de restrição, nenhuma gracinha mais vem me fazer companhia."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Muito bem, então terei que rezar para o sol se pôr rapidamente."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, já estou ansioso pelo luar desta noite."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Dizendo que sem o seu acompanhamento, mais ninguém tem permissão para me ver."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Você, ah você, me diga—ficou com ciúmes e me denunciou para a escola?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Você foi quem primeiro enfeitiçou estudantes para beberem coisas estranhas..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Aquilo era claramente um presente de amor. Sou realmente tão desprezível aos seus olhos?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Todos os dias espero por você na solidão, e ainda assim é assim que você me vê..."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Pare! Eu entendi, vou visitá-lo com mais frequência."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Que criança atenciosa. Mas eu quero ver você a cada momento—agora mesmo—não quero esperar nem um segundo."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Hoje à noite, eu venho hoje à noite, está bem!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Você foi quem primeiro enfeitiçou estudantes para beberem coisas estranhas..."
  },
  AvgCommunicate_67020_Option_7 = {
    Text = "Pare! Eu entendi, vou visitá-lo com mais frequência."
  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Hoje à noite, eu venho hoje à noite, está bem!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Guardião, desculpe incomodar. Você tem algum tempo livre recentemente?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Então você quer saber se eu poderia ir com você?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, tudo bem pra você?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Claro! Parece que vai ser muito divertido!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Obrigado, Guardião! Ter você comigo me deixa muito mais tranquilo."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Ouvi dizer que poemas escritos na hora têm chance de ganhar um prêmio. Se eu tiver sorte de conseguir um, vou dar pra você como presente de agradecimento."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "O que houve? É raro você vir me procurar por conta própria."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Bem, vai ter uma feira de poesia em Londinium. Muitos livros novos e antigos serão vendidos lá, e vários poetas vão participar para trocar ideias."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Os organizadores também me convidaram para montar um estande e compartilhar minha coleção de poesias."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "O convite deles foi tão gentil que acabei aceitando sem querer, mas..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Mas ir cuidar de um estande sozinho é muito estressante?"
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Você sempre me entende."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Mas eu não quero voltar atrás em algo que já aceitei, e o evento parece muito interessante! Ouvi dizer que vai ter até um revezamento de escrita colaborativa ao vivo."
  },
  AvgCommunicate_67021_Content_9 = {Text = "Então..."},
  AvgCommunicate_67021_Option_10 = {
    Text = "Então você quer saber se eu poderia ir com você?"
  },
  AvgCommunicate_67021_Option_12 = {
    Text = "Claro! Parece que vai ser muito divertido!"
