  },
  AvgCommunicate_67022_Content_1 = {
    Text = "Guardião, finalmente pensei num bom jeito de dormir em paz."
  },
  AvgCommunicate_67022_Content_10 = {
    Text = "Isso já é um enorme incômodo para os outros!"
  },
  AvgCommunicate_67022_Content_11 = {
    Text = "Apenas pense nisso como uma peça de arte decorativa! Eu não ronco enquanto durmo!"
  },
  AvgCommunicate_67022_Content_12 = {
    Text = "Espera, não me diga que a pessoa em quem você confia sou eu."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "Claro! O mais gentil, mais confiável e mais poderoso Guardião de Misaq — não há ninguém mais adequado para isso do que você!"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Estou planejando levar a Esfera de Sono para lá esta noite. Se quiser, posso até conversar com você antes de dormir~"
  },
  AvgCommunicate_67022_Content_15 = {Text = "Guardião?"},
  AvgCommunicate_67022_Content_16 = {
    Text = "Guardião??"
  },
  AvgCommunicate_67022_Content_2 = {
    Text = "Parabéns! Qual é o método?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "Projetei uma esfera de sono que mantém o interior iluminado durante toda a noite. Assim, não há necessidade de luzes potentes e garante que não haja pontos cegos sombrios por perto."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Parece ótimo. Agora você finalmente pode parar de invadir o quarto dos outros todos os dias e ser expulsa."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "Não! Para prevenir qualquer mau funcionamento da Esfera de Sono e evitar perigos externos, preciso colocar a Esfera de Sono em algum lugar com pessoas por perto."
  },
  AvgCommunicate_67022_Content_6 = {
    Text = "? Você quer colocar essa coisa no quarto de outra pessoa?"
  },
  AvgCommunicate_67022_Content_7 = {
    Text = "Exatamente! Vou entregar o botão de reinício de emergência da Esfera de Sono a alguém em quem confio. Assim, nada pode dar errado!"
  },
  AvgCommunicate_67022_Content_8 = {
