  AvgCommunicate_67023_Content_14 = {
    Text = "É apenas ser nocauteada, você está longe de morrer!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Obrigada, Guardião. Então vou confiar essa tarefa a você, a pessoa em quem mais confio."
