  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Não, não foi isso. Nenhum de nós queria recuar. As apostas ficavam cada vez mais altas, e nós dois já estávamos com os olhos vermelhos."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Então, na empolgação, o velho mostrou uma Vulnerabilidade, e eu Descobri que ele na verdade estava trapaceando o tempo todo."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Então você esteve dividindo vitórias e derrotas igualmente com um trapaceiro esse tempo todo?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "É, fiquei tão decepcionado. E o que é ainda mais irritante é que o velho ficou furioso de humilhação e avançou em mim pra brigar."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Ele realmente suspeitou que eu era um trapaceiro igual a ele! Que insulto."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "No final, nós dois fomos expulsos pela equipe da Lavka de Apostas. Meu traseiro ainda dói da queda. Que azar."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Não sei por quê, mas simplesmente não consigo sentir nenhuma simpatia..."
