  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Depois que entrei naquela mesa, fiquei quase empatado em vitórias e derrotas com aquele velhinho discreto."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "Isso é bem chocante. Para conseguir vencer a sua sorte, ele deve ser um verdadeiro especialista."
