  AvgCommunicate_67039_Content_12 = {
    Text = "Ainda há tantas obras que desejo completar. Preciso traçar cuidadosamente os contornos da sua alma."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Estarei aqui a Esperar por você, esperando que me conceda mais Discernimento."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "Isto é... eu, dormindo?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "No meu Discernimento, isto é você, mergulhando em um belo Sonho."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Obter uma felicidade cega e falsa, ou uma descida lúcida e dolorosa?"
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Uma escolha impossível é para sempre uma questão de arte e filosofia."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Não posso ter uma felicidade que seja ao mesmo tempo lúcida e real?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Hehe, como você é ganancioso(a)."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Nada é perfeito. Talvez nem mesmo a escultura consiga capturar a perfeição."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "Mas você sempre pode trilhar O Caminho da Mecha em busca dessa felicidade. É aí que reside o seu charme."
  },
  AvgCommunicate_67039_Option_10 = {
    Text = "Um elogio tão repentino... você está me fazendo corar..."
