  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Oh, querido(a), como você se sentiu sobre nosso doce momento juntos da última vez? Você tem saboreado isso todos os dias desde então?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Apenas diga, o que você está aprontando desta vez..."
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Não fique tão tenso, já estamos em tão bons termos～"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Confie em mim, siga-me, e eu o levarei a prazeres completamente novos."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Desta vez, gostaria de experimentar em primeira mão como velas e pequenos chicotes são usados?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Eu vou te ensinar tudo, mão a mão, pouco a pouco, querido."
  },
  AvgCommunicate_67040_Content_2 = {
    Text = "Que momento juntos?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "Eu não me lembro."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "Que crueldade! E eu fui tão gentil com você da última vez～"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Eu aconselharia você a medir suas palavras..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, se fazer de bobo(a) não vai adiantar, porque eu já usei cera para me Lembre-se de cada contorno, cada curva, cada forma sua!"
  },
  AvgCommunicate_67040_Content_7 = {
