  AvgCommunicate_67041_Content_1 = {
    Text = "Mestre, você estava gesticulando para mim. Queria dizer que desejava entrar em contato comigo?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Ai, preciso te ensinar a identificar as mulheres más na escola e providenciar algumas medidas preventivas imediatamente."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Me escute—saia da Porta dela agora mesmo. Quanto mais longe, melhor. Apenas diga a ela Depois que eu te chamei!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "M-mas eu já prometi à Lady Pandia. Não posso quebrar minha palavra."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Está tudo bem, meu senhor. Ainda há Força suficiente para me proteger!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Você, eu... Esqueça. Se insiste em ficar aí, Lembre-se disto—nunca entre no quarto dela."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Claro! Eu jamais entraria no quarto de uma dama!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Não importa o que ela diga, não entre. Me Chamar se algo acontecer. Ah, e faça o que fizer, não cheire as velas dela!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Vou me lembrar disso, meu senhor. Mas por que não posso cheirar as velas?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Não pergunte... São lições duras pagas com meu Sangue e lágrimas em seu nome..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Isso mesmo. Por que você ficou parado na frente da Porta de Pandia??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, Pandia me pediu para fazer isso. Ela disse que tinha algo muito importante para cuidar e queria que eu fosse o Guardião da porta dela."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Algo importante? Não acredite nas bobagens dela! Os tais assuntos dela... Esquece, ela com certeza te enganou!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Hã? Mas a expressão dela agora há pouco era tão solene, e ela segurava minha mão com tanta sinceridade..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Deixe-me adivinhar—ela segurou sua mão e te chamou de o Cavaleiro mais confiável e gentil."
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Como você sabia, meu suserano?!"
