  AvgCommunicate_67042_Content_2 = {
    Text = "Você quer dizer essa caixa estranha na porta que só tem o nome do destinatário?"
  },
  AvgCommunicate_67042_Content_3 = {
    Text = "Então pode vir reciclar na lixeira lá embaixo no dormitório agora."
  },
  AvgCommunicate_67042_Content_4 = {
