  AvgCommunicate_67043_Content_1 = {
    Text = "Depois de passar tanto tempo em Misaq, de repente me pego sentindo falta da lua sobre o deserto."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Venha, vamos criar novas memórias juntos — entre as flores, pelos campos abertos, para ver o oceano e os vales, as cidades e o interior."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Quero deixar memórias nossas em cada lugar bonito. Você vai ficar ao meu lado, não vai?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Então você também sente saudades de casa?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Mais do que saudades de casa, talvez eu esteja apenas relembrando as memórias que um dia compartilhei com pessoas — aquelas emoções intensas."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Não esperava que você fosse tão sentimental."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "O quê? Você acha que sou do tipo despreocupado e insensível? Não, eu me lembro de cada pessoa, de cada memória calorosa e doce."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Incluindo as que tenho com você."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Devo me sentir honrado ou ciumento?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Adoro ver você todo atrapalhado assim. Que adorável."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Embora os dias passados mereçam ser saboreados, a alegria desta noite é a mais preciosa de todas."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Então você também sente saudades de casa?"
