  AvgCommunicate_67043_Option_4 = {
    Text = "Não esperava que você fosse tão sentimental."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "Devo me sentir honrado ou ciumento?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Recentemente tenho projetado um lote de acessórios para adornar minha coleção."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Se quiser, por favor aceite estes colares que selecionei cuidadosamente. Desta vez, são um presente gratuito."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Se encontrar um de que goste depois de experimentá-los, por favor não deixe de me avisar."
