  AvgCommunicate_67044_Content_12 = {
    Text = "Mesmo que o seu crânio ainda não me pertença, só de ver você usando já seria o suficiente para me trazer alegria."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Há vários estilos para escolher, e estou tendo dificuldade em decidir, então queria pedir seu conselho."
