  AvgCommunicate_67044_Content_5 = {
    Text = "Ah, meus preciosos crânios, é claro."
  },
  AvgCommunicate_67044_Content_6 = {
    Text = "Eu olhei várias revistas de moda e designs de joalherias."
  },
  AvgCommunicate_67044_Content_7 = {
    Text = "Todos os tipos de colares têm seu próprio charme, e há até estilos de choker mais exclusivos. É uma escolha tão difícil."
