  AvgCommunicate_67045_Content_1 = {
    Text = "Ai, os negócios na minha lojinha andam ruins ultimamente. Faz muito tempo que não encontro uma cabeça que me satisfaça."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Se vocês dois cooperassem para caçar alguns grandes criminosos procurados, poderiam até criar uma lenda de vigilantes urbanos que punem o mal."
  },
  AvgCommunicate_67045_Content_11 = {
    Text = "Não é uma má sugestão, mas um sujeito esperto como aquele não é fácil de enganar."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "Pensando bem, aquela cabeça peculiar dele seria bastante digna de adicionar à minha Coleção. Que pena não haver oportunidade para uma troca. Que lamentável."
  },
  AvgCommunicate_67045_Content_13 = {
    Text = "Espero que o Ryker não esteja a espirrar agora..."
  },
  AvgCommunicate_67045_Content_2 = {
    Text = "Hmm... Cabeças são de fato algo que não dá exatamente para sair comprando."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Então recentemente firmei uma cooperação com o Comitê de Revisão. Eu os ajudo a rastrear fugitivos e, em troca, eles me fornecem secretamente as cabeças de criminosos executados."
  },
  AvgCommunicate_67045_Content_4 = {
