  AvgCommunicate_67045_Content_6 = {
    Text = "Claro, não é um tipo oficial de cooperação, mas sempre há pessoas espertas em todo lugar."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "Também tentei contactar a polícia de Londinium, mas eles parecem confiar mais naquele detetive com cabeça de cão."
  },
  AvgCommunicate_67045_Content_8 = {
    Text = "Como alguém se adiantou no negócio, não tive escolha senão procurar noutro lugar."
  },
  AvgCommunicate_67045_Content_9 = {
    Text = "Hmm... Embora eu ache que o Ryker também não se importa muito com esse negócio."
  },
  AvgCommunicate_67045_Option_13 = {
