  AvgCommunicate_67046_Content_10 = {
    Text = "O pensamento de estar envolvido no crescimento de Pony desde jovem me empolga!"
  },
  AvgCommunicate_67046_Content_11 = {
    Text = "Então criar cavalos começa a uma idade tão jovem?"
  },
  AvgCommunicate_67046_Content_12 = {
    Text = "Um cavalo é o mais próximo companheiro do cavaleiro! Quanto mais confiança entre eles, melhor."
  },
  AvgCommunicate_67046_Content_13 = {
    Text = "Eu sempre quis ter um cavalo que eu criei desde potro!"
  },
  AvgCommunicate_67046_Content_14 = {
    Text = "Eu posso ver que você realmente está ansioso por isso."
  },
  AvgCommunicate_67046_Content_15 = {
    Text = "Se eu tiver tempo então, eu irei e te ajudarei."
  },
  AvgCommunicate_67046_Content_16 = {
    Text = "Estou também curioso para ver que tipo de padrão o pônei terá."
  },
  AvgCommunicate_67046_Content_17 = {
    Text = "!! Estarei bem preparado!"
  },
  AvgCommunicate_67046_Content_2 = {
