  AvgCommunicate_67046_Content_4 = {
    Text = "Então, então existe essa possibilidade? Isso é realmente incrível..."
  },
  AvgCommunicate_67046_Content_5 = {
    Text = "Haha, só estou brincando! É perigoso acreditar em tudo que os outros dizem."
  },
  AvgCommunicate_67046_Content_6 = {
    Text = "E-eu serei mais cuidadoso da próxima vez! Mas se é por você, meu senhor, não há necessidade de suspeitas!"
