  AvgCommunicate_67047_Content_1 = {
    Text = "Guardião, gostaria de te pedir um favor."
  },
  AvgCommunicate_67047_Content_10 = {
    Text = "Com você ao lado Dela, ela certamente se sentirá mais à vontade e vai Liberar."
