  AvgCommunicate_67047_Content_2 = {
    Text = "Qual é o problema?"
  },
  AvgCommunicate_67047_Content_3 = {
    Text = "Você poderia levar a Tinta a algumas reuniões para que ela possa fazer novos amigos?"
  },
  AvgCommunicate_67047_Content_4 = {
    Text = "Desde o nosso Reencontro, ela fica grudada em mim todos os dias, completamente isolada do mundo exterior."
  },
  AvgCommunicate_67047_Content_5 = {
    Text = "Embora eu também valorize nosso Reencontro, não quero mantê-la completamente presa ao meu lado."
  },
  AvgCommunicate_67047_Content_6 = {
    Text = "Isso não é difícil, mas você já considerou como a Tinct se sente sobre isso?"
  },
  AvgCommunicate_67047_Content_7 = {
    Text = "Eu conheço Ela... mas ela não pode continuar se recusando a se aproximar de Todos só por minha causa."
  },
  AvgCommunicate_67047_Content_8 = {
    Text = "Talvez você também não precise afastá-la de forma tão decisiva."
  },
  AvgCommunicate_67047_Content_9 = {
    Text = "Que tal eu levar vocês dois, você e a Tinct, juntos a um encontro? Vou garantir que as devidas precauções estejam em vigor."
