  AvgCommunicate_70495_Content_7 = {
    Text = "Acompanhara o novo Investigador, indo constantemente para os lugares mais perigosos."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Até que aquele Investigador resignasse ou morresse."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Talvez, um dia nós..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Você sentirá medo?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Eu nunca senti seu medo."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "O que a escola fará com esta chave de prata...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Vamos acabar como Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "O ritual deste povo Aram... é verdadeiramente chocante."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Sou eu esse tipo de pessoa?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Eu estava apenas perguntando de forma casual, por que tanta tensão?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Fazer isso fará de você um livro aberto na mesa de cartas. Sua fortaleza mental precisa de melhorias, Guardião."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "Em resumo, os segredos deste deserto são provavelmente muito mais complexos do que antecipamos."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "A investigação subsequente requer cautela extra."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Achei que você aceitaria o convite daquela mulher de Aran."
  },
  AvgCommunicate_70496_Content_3 = {Text = "..."},
  AvgCommunicate_70496_Content_4 = {
    Text = "Que tipo de imagem eu realmente tenho em seu coração..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Eu nunca esperei que Ryker, que costuma ser tão charmoso, também tivesse coisas que não conseguia aceitar."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Não há histórias com flores e vinho, apenas os desejos mais primitivos e selvagens."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Este tipo de ritual realmente não é do meu agrado."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Falando nisso, você não aceitou nenhum convite estranho, certo?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Quando... claro que não... como poderia ser!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Eu pensei que você aceitaria o convite daquela mulher Aylan."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Eu não esperava que houvesse coisas que você não pudesse aceitar também."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Quando... claro que não... como poderia ser!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Olá, Guardião dos Segredos {Male=senhor,Female=senhora}."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Você se divertiu brincando com os brinquedos da Juliette?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Você é... o infiltrado?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Eu pensei que você teria descoberto quem sou mais cedo. Que pena."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Mas tudo bem; afinal, é apenas o jogo final."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Agora, o jogo está prestes a acabar."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Antes que a destruição destinada chegue, estou curioso apenas sobre uma coisa."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "A eterna verdade do Caos, o ousado Guardião de quem falamos sem vergonha, Mythag, o bravo Salvador, pode realmente enfrentá-la com coragem?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Você é... o infiltrado?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Não sou um comerciante tolo, mas após cuidadosa consideração, parece que fiz um negócio desvantajoso..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Estar sempre atento a mentiras é uma qualidade básica de um empresário qualificado."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Então... aquela era realmente a verdadeira face da Senhora Davendale?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Não há custo mais caro do que a realidade, pequeno Guardião."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Obrigado, Senhora Narciso."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "O que eu acabei de dizer foi uma piada. Eu sei o que significa para alguém como você revelar seu verdadeiro eu."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Este é um presente precioso, e eu o valorizarei bem."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Não pense que você pode me ignorar com apenas algumas palavras, pequeno."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "Em troca, você não deveria também me dar um presente?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Eu fui visto...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Senhora Davendale, o que deseja?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Desde que você já viu minha verdadeira forma, quando você estará pronto para me mostrar seu verdadeiro eu?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Meu verdadeiro eu? O que isso significa... Eu não entendo muito bem, Senhora Narciso."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Parece que Mythag ainda não te contou nada..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "A hora ainda não chegou. Sem preocupações."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Lembre-se do nosso acordo hoje, pequeno."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Estou ansioso pelo dia em que você revelará seu verdadeiro rosto."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Você já não obteve a cabeça que desejava?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Aquele vibrante mar de matéria cinza se tornou mais uma peça preciosa na sua coleção."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "De fato, era uma cabeça bonita; este negócio não pode ser considerado uma perda."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "No entanto, o custo que paguei ainda é um pouco alto demais."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Você só me deu uma visão do seu verdadeiro eu..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "E se é realmente assim que você se parece, é difícil dizer."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Hehe... Nada mal, pequenino."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Então... aquela era realmente a verdadeira face da Senhora Davendale?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Obrigado, Senhora Narciso."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Eu fui visto...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Já não obtivemos a cabeça?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Meu verdadeiro eu? O que isso significa"
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Só consegui vislumbrar sua verdadeira forma..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Eliminando dissentores, ela se libertou das restrições de Longbel e do Contrato. Sem esses impedimentos, em apenas algumas semanas, ela se tornou a caçadora mais feroz no mundo dos negócios de Londinium."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Não se preocupe, Professor Dexter. Não vamos deixar você fazer coisas tão perigosas da próxima vez... Quer dizer, vamos tentar não deixar."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "A existência oculta na consciência de Sorel parece ser chamada de \"N\". Você sabe algo sobre ele?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Não muito claro. Parece mais um golpista ou um louco, provavelmente ambos."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Mas não importa quão hediondo, pelo menos esse cara tem bom gosto. Você pode perceber pelo canto dele."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "Na próxima vez que houver uma oportunidade, precisamos nos conhecer melhor. Talvez possamos até compartilhar uma bebida ou duas."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Claro, em um ambiente seguro. O gentil senhor não pode suportar mais nenhum susto."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Eu acho que não vai demorar para que toda a terra de Londinium carregue seu sobrenome."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "A Dama Sorel, que pessoa fascinante. Felizmente, Mythag está ao seu lado."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Eu devo esse assunto à sua ajuda, Professor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Obrigado por ajudar a atrair o suspeito; caso contrário, teria levado muito mais tempo para resolver este assunto."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Simplesmente cumprindo os deveres de um cavalheiro."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "A proposta apresentada por Ramona, este meu velho pai não tem direito de recusar."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "No entanto, se algo assim acontecer novamente da próxima vez, espero que você possa agir um pouco mais rápido."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Não espere até que a faca daquele cara esteja a apenas cinco centímetros do meu pescoço para aparecer; é realmente assustador."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Não haverá uma próxima vez... Eu farei o meu melhor."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Você sabe sobre \"N\"?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Obrigado por ajudar a atrair o suspeito"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "A conversa no café foi bastante agradável, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Então, se essa situação ocorrer novamente, você ainda atiraria em mim mesmo para salvar os outros? Você atiraria?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... claro."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Fique tranquilo, {Male=Mr.,Female=Miss} Guardião. A sorte ainda vai sorrir para mim."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "Naquele momento, minha arma definitivamente não tinha balas."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% não."},
  AvgCommunicate_70500_Content_2 = {
    Text = "É uma honra testemunhar o passado de um jogador."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Minha parte favorita é quando o jogador perde tudo e tem sua Alma roubada por outros."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... há vitórias e derrotas, essa é a vida."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Olhe, não ganhamos uma vantagem desta vez?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Então o tiro que você disparou em mim também foi uma aposta?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Como isso pode ser? Estou 70% certo do meu julgamento."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "E quanto aos 30% restantes?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Não há 30% restantes. 70% é equivalente a 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "É uma honra testemunhar o passado de um jogador."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Então o tiro disparado contra mim também foi uma aposta?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "E quanto aos 30% restantes?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Tem boa aparência?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Mas... a história contada por esse conjunto de esculturas é demasiado cruel."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Compreendeu, Guardião..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Toda criação é cruel."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "É precisamente nessa crueldade que a arte imóvel ganha uma vida vívida."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Se fosse eu, acho que acharia o processo de tal criação incrivelmente árduo..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Mas você é diferente, Sanga. Compreendo a sua escolha."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Uma obra como \"Morte da Sra. Coral\" é o significado que você persegue."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Estou ansiosa por isso—por ver essa \"crueldade\" florescer mais uma vez nas linhas que você esculpe."
  },
  AvgCommunicate_70501_Content_18 = {Text = "..."},
  AvgCommunicate_70501_Content_19 = {
    Text = "Pensei que você seria como aqueles filisteus e sugeriria que minha arte fosse mais \"normal\"."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "O que... seu rosto?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Essas palavras significam muito para mim... Obrigada, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Como recompensa, deixe-me contar um pequeno segredo: quando você entrou em Sonhar, eu estava bem ao seu lado."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Todas aquelas suas expressões desprevenidas—eu esculpi cada uma delas. Fiéis · à · realidade."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Quando tiver tempo, venha visitar meu pequeno hall de exposições~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga! Eu te dou cinquenta Presas de Leo, então por favor jogue fora aquelas Esculturas..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "O que você chamou de arte vívida, porém \"cruel\". Não é mesmo, Guardião?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "A escultura que viu no Sonho, claro."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "As linhas da carne são naturalmente harmoniosas, mas carecem da beleza eterna da quietude, e falta-lhes tema e visão criativa — dificilmente comparáveis a obras esculturais."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Muito poucas pessoas viram esse conjunto de esculturas agora. Gostaria de saber a sua avaliação..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "O quê... as suas esculturas?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Claro. Muito poucas pessoas viram esse conjunto de esculturas agora. Gostaria de saber a sua avaliação..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Esse é o conjunto de esculturas mais belo que já vi."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Embora as linhas sejam estáticas, capturam um dinamismo e uma vitalidade que nem mesmo seres vivos possuem."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Eu entendo sua escolha"
  },
  AvgCommunicate_70501_Option_2 = {Text = "Seu rosto?"},
  AvgCommunicate_70501_Option_24 = {Text = "Não!!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "As suas esculturas?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Belas... e cruéis."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Chato. Chato, chato, chato..."
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Londinium não permite escravidão, este lugar bárbaro."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Não tenho escolha senão ouvir-te e mandar neles Dentro do labirinto."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "A maneira como lutavam na arena era exatamente como eu tinha visto antes!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Então o Labirinto é usado para esse propósito..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Isso mesmo, isso mesmo! Que fascinante!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Vamos, vamos dar uma olhada! Esta é a maior honra!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Não é impossível; aprender mais sobre a história não é uma coisa ruim..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Uvhash provavelmente realmente gostará da sua arena. Por que não convidá-lo também?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Não! Mantenha esse demônio bem longe!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Presa neste lugar maldito todos os dias, estou tão farta disto!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "Eu reconstruí meu labirinto, uma verdadeira arena construída de acordo com minhas memórias!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Vamos divertir-nos juntos! Agora mesmo!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Quando você vai mudar esse tom que usa para comandar escravos...?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, o que há para mudar nisso?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "Eu já cedi dez mil vezes! Agora eu só comando aqueles escravos no Labirinto."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "Você não tem medo de relembrar essas coisas agora?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "De fato. O que há para temer!"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Então eu vou chamar o Uvhash também."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Quando você vai mudar seu tom..."
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "Você não tem medo de relembrar essas coisas agora?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "O incidente que ocorreu na igreja... Se você não estivesse lá, mais pessoas inocentes teriam sido feridas..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Mas agora, ela é a líder atual da Igreja da Luz do Templo."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "O quê? O líder da Igreja da Luz do Templo?!!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "No mundo religioso, a Igreja da Luz do Templo é a maior inimiga da sua igreja... Como é que o seu aluno...?"
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Um longo conto, Mensageiro."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Ela trabalhou uma vez comigo pela causa do Pai Deus, dedicando tudo o que tínhamos ao povo do Pai Deus."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Mas, como você pode ver, não é tão fácil para os desajustados se afastarem do Deus Pai. Aqueles atos atrozes e preconceitos não podem ser dissipados apenas com algumas Bençãos."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Por causa das tribulações que suportei, ela embarcou em um caminho do qual seria difícil voltar."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Então é assim que é..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Eu entendo. Assim como o que aconteceu antes na igreja, aqueles que não mudaram por suas boas ações causaram a transformação dela..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "O Deus Pai nos ensinou uma vez que as questões neste mundo nem sempre são pretas e brancas. Boas ações também podem, às vezes, ser um erro."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "Em nome da Igreja e dos inocentes sobreviventes, expresso minha sincera gratidão a você, o Mensageiro Pálido."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "Eu dediquei tudo às vítimas, mas esqueci que meu aluno também é uma delas."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "A igreja e minhas crenças podem ter salvado muitas pessoas, mas falharam em salvá-la."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Não sou um professor qualificado, Mensageiro."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Eu continuarei a caminhar pelo caminho do Deus Pai. Mas me pergunto se algum dia terei a chance de compensar esse arrependimento em relação àquele estudante..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "De nada, Bispo Salvador. É tudo parte do meu dever."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Bispo, sobre seu passado, há uma questão que eu gostaria de te perguntar..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Fale sem reservas, Enviado."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Meu passado estará aberto a cada pessoa sob a proteção do Pai Deus."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Quando me conectei com você, além da Sophia, vi uma mulher tendo uma conversa com você."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Aquela memória ocupa uma grande parte do seu Espírito... Todos vocês estão muito familiarizados com isso?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "De fato, muito familiar. Uma vez, ela foi minha aluna mais excepcional."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "O líder da Igreja da Luz do Templo?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Então é assim que é..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "É tudo que eu deveria fazer."
  },
