  AvgCommunicate_72037_Content_10 = {
    Text = "Nada escapa ao seu olhar."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "O que paira no sonho é uma sensação particularmente acolhedora e familiar. Yu, no início, pensou que fosse algo trazido por Noa."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Só depois percebi que, ao longo dos longos anos, o que estava mais familiar para mim já não era uma pessoa, mas sim um objeto frio e inanimado."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "Retire sua compaixão. Desde o momento em que coloquei a coroa, já estava totalmente preparado."
