  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Então... Rei da Lemúria, você está interessado em experimentar aquele doce de arroz novamente? Eu acho que o chef de Mythag deve ser capaz de recriá-lo até certo ponto."
  },
  AvgCommunicate_72037_Content_17 = {Text = "..."},
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmm, você é bastante atencioso."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Muito bem, considere isso seu tributo."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Aquelas são as memórias que nunca gostei de falar, mas, no sonho de ontem, foi você, não foi?"
