  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Além de profecias, às vezes tenho sonhos como pessoas comuns, mas nenhum desses sonhos é tão vívido e contínuo quanto o sonho de ontem..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Como se alguém estivesse sentado ao meu lado, revivendo todos os eventos do passado desde o início."
  },
  AvgCommunicate_72037_Content_7 = {
