  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, se for conveniente, poderia vir fazer um teste psicológico?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... quando sozinho, suas figuras sempre flutuam em minha mente."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "Não precisa suportar isso sozinha. Quaisquer problemas e confusões que você tenha, você pode me contar."
