  AvgCommunicate_80100_Content_13 = {
    Text = "...Estou indo agora."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...Um teste psicológico?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "É muito simples. Você só precisa desenhar uma casa, uma árvore e uma pessoa em uma folha de papel em branco."
