  },
  AvgCommunicate_80100_Content_5 = {
    Text = "...Mas eu acho que minha saúde mental está perfeitamente bem."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "O objetivo final do teste não é julgar a saúde, mas observar potenciais problemas psicológicos."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, depois de vir aqui, você sente solidão? Você sente falta dos amigos daquele mundo?"
  },
  AvgCommunicate_80100_Content_8 = {
