  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...Um teste psicológico?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "...Mas eu acho que minha saúde mental está perfeitamente bem."
  },
  AvgCommunicate_80100_Option_9 = {Text = "..."},
  AvgCommunicate_80101_Content_1 = {
    Text = "Ouvi que você tem se sentido mal ultimamente; se não se importar, você pode vir até mim para uma consulta."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah, apenas descrever isso faz meu coração prateado tremer sem parar..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, mal posso esperar para me aprofundar em seu coração e saborear suas memórias."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Então você ficará desapontado. Eu já fui embora."
