  AvgCommunicate_80101_Content_13 = {
    Text = "Eu sei. Um dos meus pacientes me enviou uma mensagem para me informar sobre este assunto."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "Ela até anexou cuidadosamente sua localização atual, então..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "Estarei lá em breve."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "Não precisa se exibir, Guardião. Sugestões de profissionais podem ajudá-lo a ajustar seu estresse mais rápido."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "Como você poderia saber essas...?"
