  AvgCommunicate_80101_Content_4 = {Text = "Segredo~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Então, qual é a sua resposta?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Eu prometo que desta vez não farei nenhuma outra orientação."
  },
  AvgCommunicate_80101_Content_7 = {
