  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Isso não é minha culpa, mas sim que sua consciência está cheia de memórias agradáveis."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Essas memórias superam de longe a dor que uma pessoa comum pode suportar, e carregam a aura daquela grande existência, que é a doçura mais suprema."
  },
  AvgCommunicate_80101_Option_12 = {
