  AvgCommunicate_81324_Content_11 = {
    Text = "Isso mesmo, pense nisso, quando pedi para você escrever aquelas duas tarefas, eu queria explorar você para trabalho gratuito ou esperava que você tivesse uma oportunidade de aprendizado?"
