  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Cof, cof... Bem, vamos pensar novamente. Quando realizamos uma ação com uma pessoa como o objetivo final, considerando sinceramente um ao outro, isso pode ser chamado de moral."
