  AvgCommunicate_81325_Content_10 = {
    Text = "Isso não é o caso, é apenas que esses dois assuntos estão atualmente se desenvolvendo também, e muitos acadêmicos irão ampliar e aprofundar esses estudos, criando novos conhecimentos."
