  AvgCommunicate_84107_Content_1 = {
    Text = "Quando termina este feriado?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Ao somar e analisar esses fatores, é possível planejar a rota mais eficiente e racional."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "……Entendi. Parece que cada trabalho tem seu próprio significado."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Sim, já que fiz a minha escolha, preciso assumir a minha responsabilidade."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "A partir de agora, também farei a ronda noturna todos os dias, garantindo que não ocorram incidentes na academia durante o período de férias."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Guardião do Segredo, por enquanto é só. Preciso ir trabalhar."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...o feriado não acabou de começar?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Estou apenas me preparando para o que vem depois."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "O mapa da academia foi atualizado, o relógio foi calibrado e as bandeiras e mastros foram limpos."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Todos os dias após isso, também vou continuar com a manutenção, garantindo que possa iniciar o trabalho a qualquer momento."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...É tanta preparação assim só para o trânsito durante o almoço na Academia de Comando?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Claro. Qual cantina é mais popular, qual faculdade tem mais alunos e quais alunos desejam prioridade para ir à cantina influenciarão o planejamento de toda a rota."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Ainda há qual canteiro de flores que foi transformado em lar por gatos vadios recém-chegados, qual área foi pisoteada pelos estudantes criando um novo caminho, e qual estrada necessita de manutenção..."
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "……Entendi."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...o feriado não acabou de começar?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Apenas o trânsito durante o horário do almoço na Academia de Comando..."
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Guardião, peço sinceras desculpas pelo incidente da última vez."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Mas como não estamos no mar, fiz alguns ajustes de acordo com as circunstâncias."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Esses ajustes não seriam por acaso... se algemar a mim, seriam..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Sim. Dessa forma, caso algo dê errado comigo, você pode detectar e intervir imediatamente."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "...Posso recusar?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Você com certeza pode recusar."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Mas eu já estou à sua porta."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "...Você quer dizer a vez em que sua insônia fez o Fogo de Santelmo sair de controle?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Mesmo que Fusão - Boneca me tenha nocauteado a tempo, ainda me sinto envergonhado."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Pensei sobre isso por muito tempo e concluí que mereço ser punida."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Isso realmente não é necessário. O último incidente não causou nenhuma consequência grave."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Não, erros devem ser acompanhados de punição. São as regras."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Já prendi uma ponta das algemas em mim. A outra ponta requer sua cooperação."
