  AvgCommunicate_84108_Content_8 = {
    Text = "Meu cooperação?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Normalmente, aqueles que cometem erros em um navio são acorrentados pelas pernas e deixados para assar no convés por várias horas."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Esses ajustes não seriam por acaso..."
