  AvgCommunicate_84109_Content_10 = {Text = "..."},
  AvgCommunicate_84109_Content_11 = {
    Text = "Na verdade..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "Na verdade? Por que você está de repente gaguejando ao falar, isso não é como você."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "Na verdade, você não precisa visitar o museu marítimo; apenas \"relaxar\" um pouco deve ser o suficiente."
