  AvgCommunicate_84109_Content_14 = {
    Text = "Embora eu não compreenda o que você quer dizer com \"relaxamento\" normal, eu me sinto calmo quando estou com você."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Sinto como se estivesse em um mar calmo, sem tempestades, e sem encontrar tempestades, apenas seguindo o curso, podemos alcançar nosso destino em segurança."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "......Embora esta metáfora seja difícil de entender, eu entendo mais ou menos o que você quer dizer."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "No futuro, podemos explorar diferentes lugares. Este mundo é vasto, além dos oceanos, há muitas paisagens bonitas."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "......Eu entendo. Eu vou tentar."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Veja... a bela paisagem que é diferente do oceano."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Por que agradecer de repente?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Nesta viagem ao Museu Marítimo de Londres, aprendi muito."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Os relógios marítimos expostos, os mapas náuticos desenhados à mão e os fragmentos dos diários de navegação todos contribuem para a melhoria das habilidades de navegação."
