  AvgCommunicate_84110_Content_10 = {
    Text = "Espere, como isso poderia ficar mais absurdo!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Onde está Winkle agora?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Bem aqui, conduzindo experiências no dispositivo de condução, testando se a energia de @2<AvgCommunicateConfuseColor.Light> pode ser transformada em energia luminosa."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Por que você não recusa?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Por que recusar? Servir os passageiros é um dos meus deveres."
  },
  AvgCommunicate_84110_Content_15 = {Text = "..."},
  AvgCommunicate_84110_Content_16 = {
    Text = "Estou indo agora. Você segura o Búzio para mim."
  },
  AvgCommunicate_84110_Content_17 = {
