  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Por exemplo, testando a intensidade de @2<AvgCommunicateConfuseColor.Light> com um medidor de corrente de impacto, escaneando as linhas espectrais de @2<AvgCommunicateConfuseColor.Light> com um prisma, usando uma plataforma de teste humano para verificar a conexão de @2<AvgCommunicateConfuseColor.Light> com fibras nervosas..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Espere, como isso poderia ficar mais absurdo!"
