  },
  AvgCommunicate_84110_Option_6 = {
    Text = "A solicitação de suprimentos foi aprovada..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Graças à sua apresentação, após conhecer Lorde Ogier, ele nos apresentou a mais amigos."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "O Senhor Ogier também mencionou que o treinamento de cavaleiros é ainda mais complexo e tedioso do que isso, parece que, como afirmado nos livros, cada cavaleiro é de fato uma pessoa digna de respeito."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Claro, Ogier é o mais dedicado nos treinos entre os Despertados!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Também descobrimos que mesmo com uma deficiência, a Instrutora Alva está fazendo o mesmo treinamento que nós."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Inicialmente, pensávamos que a Instrutora Alva também era uma cavaleira, mas ela disse que costumava ser uma soldado. Não sei que tipo de profissão é essa, mas deve ser tão respeitável quanto a de um cavaleiro."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Soldados são aqueles que lutam pelo país, o que também pode ser considerado um tipo de cavaleiro; no entanto, em comparação com os códigos morais rígidos dos cavaleiros, as ações dos soldados não necessariamente representam a justiça."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva só percebeu isso após deixar o exército; talvez a vida agora seja mais confortável para ela."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Entendo, o que você quer dizer é que um cavaleiro representa não apenas poder, mas um espírito de justiça, como o Instrutor Alva e pessoas justas como você, todos possuem a alma de um cavaleiro."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Embora você tenha falado muito bem, isso é bastante constrangedor..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Isso é uma boa notícia; estou realmente feliz por você."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Já encontramos muitos despertadores e, como você disse, a maioria deles são pessoas gentis."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Sinto vergonha ao lembrar de quando cheguei aqui pela primeira vez, eu costumava ter dúvidas suspeitas sobre os outros."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "Na verdade, não é tão ruim porque há muitas pessoas que merecem cautela..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Agora estou com Castor, participando do curso de treinamento do Instrutor Alva juntamente com o Lorde Ogier"
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "A postura de batalha do Senhor Ogier é verdadeiramente deslumbrante, mas ele mesmo parece não estar acostumado a elogios, que pessoa humilde."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ha ha, Ogier é só um pouco tímido, é só conversar normalmente com ele."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Acontece que Castor e eu nunca recebemos treinamento de batalha na igreja; tal treinamento intenso é realmente difícil, no entanto, Lorde Ogier diz que faz isso todos os dias; que grande perseverança."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Claro, Ogier é o mais dedicado nos treinos entre os Despertados!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Eu suponho..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Isso é uma boa notícia; estou realmente feliz por você."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "Na verdade, não é tão ruim porque há muitas pessoas que merecem cautela..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier é apenas facilmente tímido."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Respeitoso senhor, obrigado por preparar um abrigo para mim e Castor."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Aquele cara Castor gostava de se lavar cinco vezes ao dia, mas depois que eu o impedi, virou três vezes ao dia."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Lavar seu rosto muitas vezes pode causar danos!!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Mas vocês nunca usaram essas coisas antes? Não imaginei que a Igreja da Luz do Templo fosse tão mesquinha."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "De fato, não, mas não porque a igreja é mesquinha, mas como Filho, sempre fomos exigidos a reprimir desejos e focar na prática."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Praticamente nunca tivemos contato com esses produtos tecnológicos, e há muitas regras em relação às nossas vidas diárias e refeições."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Embora as roupas e a comida sejam geralmente luxuosas, você não pode comer exceto durante os horários das refeições, e deve deixar os alojamentos assim que é hora de se levantar."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Quando criança, eu costumava imaginar quando poderia parar de acordar cedo e comer o que quisesse o dia todo."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "Nesses dias, tenho visto repetidamente uma jovem carregando comida passar à tarde; parece que a vida que eu sonhei aqui já se tornou rotina."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, é provável que Murphy tenha ido buscar os bolinhos... de fato, sua vida parece realmente cansativa."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Eu ouvi Castor dizer que uma cama havia sido especialmente adicionada à casa, então eu sabia que deveria ser sua obra."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Tudo já passou, aqueles erros e distorções permanecerão no passado. Nós embarcaremos no caminho certo com um aspecto completamente novo, por favor, sejam testemunhas."
  },
  AvgCommunicate_94501_Content_21 = {
